insert into mother_activities (id, category, month_postpartum, applies_to, title, description, duration_minutes, time_of_day, with_baby, effort_level, progression_notes) values
  ('belly-breathing-m1', 'physical_recovery'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Belly Breathing', 'Lie on your back, knees bent, one hand on belly. Breathe in through your nose — belly rises, chest stays still. Out slowly through pursed lips for 6 counts. 5 repetitions, twice daily. This is the foundation every other physical recovery step is built on. Start here before anything else.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: 10 reps. Month 3: add gentle pelvic floor awareness on each exhale.'),
  ('foot-pumps-m1', 'physical_recovery'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Foot Pumps', 'Lying down, flex and point both feet for 30 seconds, then circle each ankle 5 times each direction. Every 1–2 hours in the first week. This is blood clot prevention — a genuine risk in the first 6 weeks postpartum. Do not skip it.', 3, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue through month 2. Replace with short walks as mobility returns.'),
  ('feeling-your-body-down-there-m1', 'physical_recovery'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Feeling Your Body Down There', 'Close your eyes and simply notice the pelvic floor without trying to contract it. Imagine it softening and releasing downward. The area may feel tight, numb, or sore — noticing without effort is the right starting point. No squeezing yet.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: begin gentle contractions after your 6-week check if cleared.'),
  ('daily-oil-massage-m1', 'physical_recovery'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Daily Oil Massage', '15 minutes of warm oil massage on arms, legs, and back. Warm sesame oil is the traditional choice — Ayurveda recommends it for its warming properties in this period. It supports circulation, reduces stiffness, and calms the nervous system. This is rehabilitation, not indulgence.', 15, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue daily through month 2, then 3–4×/week.'),
  ('healing-foods-m1', 'physical_recovery'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Healing Foods', 'The traditional Indian postpartum diet is nutritionally sophisticated. Gondh ke laddoo (edible gum, ghee, dry fruits) supports tissue healing. Ajwain water aids digestive recovery. Methi laddoo supports milk supply. Haldi doodh is anti-inflammatory. Aim for 2–3 laddoos daily and warm liquids throughout.', 0, 'anytime'::mother_activity_time_of_day, 'optional'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue through month 3. Month 4: broaden to a balanced whole-foods diet with continued iron and calcium emphasis.'),
  ('40-days-of-rest-m1', 'physical_recovery'::mother_activity_category, 1, 'all'::mother_activity_relevance, '40 Days of Rest', 'The 40-day chilla is one of the most evidence-aligned traditional practices anywhere: enforced rest, nutritional support, and reduced household burden during the hardest recovery window. Even if a full chilla isn''t possible, adopt the principle — your only job right now is to recover and feed your baby. Delegate everything else.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Most critical weeks 1–4. Month 2: expand activity gradually within your own capacity.'),
  ('check-your-cut-every-day-m1', 'physical_recovery'::mother_activity_category, 1, 'caesarean'::mother_activity_relevance, 'Check Your Cut Every Day', 'Once daily after bathing, gently pat the wound dry and check it. Normal: mild bruising, numbness, itching as healing begins. Abnormal: redness spreading beyond the scar line, warmth, swelling, discharge, wound edges separating, foul smell, or fever above 38°C. If in doubt, call your doctor the same day — wound complications are far easier to treat early.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: wound should be closed. Begin gentle surface cleaning.'),
  ('safe-way-to-get-out-of-bed-m1', 'physical_recovery'::mother_activity_category, 1, 'caesarean'::mother_activity_relevance, 'Safe Way to Get Out of Bed', 'Never sit straight up from lying. Roll onto your side first, push up sideways with your arms, then lower your legs to the floor. This protects the incision from the full load of a sit-up. Use it every single time for at least six weeks, and teach your partner so they can remind you.', 2, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue until your 6-week check. Month 3: gradual sit-up motion if healing well.'),
  ('fix-shoulder-pain-after-surgery-m1', 'physical_recovery'::mother_activity_category, 1, 'caesarean'::mother_activity_relevance, 'Fix Shoulder Pain After Surgery', 'Many C-section mothers get unexpected shoulder and neck pain in the first week, caused by residual gas in the abdominal cavity irritating the diaphragm. It is entirely normal. Relief: lie on your left side with a pillow between the knees, do slow belly-led breathing, gentle shoulder rolls, and a warm cloth on the neck. It usually resolves in 5–7 days.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'If shoulder pain persists beyond 10 days, tell your doctor.'),
  ('hold-a-pillow-when-you-cough-m1', 'physical_recovery'::mother_activity_category, 1, 'caesarean'::mother_activity_relevance, 'Hold a Pillow When You Cough', 'Hold a folded towel or pillow firmly against your incision whenever you cough, sneeze, or laugh. The sudden intra-abdominal pressure of a cough is significant and unsupported coughing in the first weeks causes real pain and unnecessary strain on the healing wound. Keep a small pillow within reach wherever you sit.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue for at least 4 weeks or until coughing is comfortable without support.'),
  ('nothing-heavier-than-baby-m1', 'physical_recovery'::mother_activity_category, 1, 'caesarean'::mother_activity_relevance, 'Nothing Heavier Than Baby', 'For the first six weeks, lift nothing heavier than your baby. This is the single most commonly ignored surgical instruction and the most common cause of wound complications and hernia. Arrange help for toddlers, shopping, and laundry baskets in advance rather than discovering the limit by injuring yourself.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: reassess at your 6-week check before lifting anything heavier.'),
  ('soft-belly-support-band-m1', 'physical_recovery'::mother_activity_category, 1, 'caesarean'::mother_activity_relevance, 'Soft Belly Support Band', 'A soft, non-compressive binder or well-wrapped muslin provides gentle support and proprioceptive feedback to the healing abdomen. Wear 4–6 hours during waking hours only, never at night, and make sure it does not press directly on the incision. This is support, not compression — quite different from a waist trainer.', 0, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: reduce wearing time as core awareness returns. Month 3: discontinue and begin structured core work.'),
  ('sad-days-or-something-more-m1', 'emotional_wellness'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Sad Days or Something More', 'Baby blues (days 3–10) means weepiness and mood swings that resolve on their own. Postpartum depression means 2+ weeks of persistent sadness, hopelessness, difficulty bonding, or intrusive thoughts — and it responds very well to treatment. If you''re unsure which you''re experiencing, tell your doctor. There is no shame in either.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: take the Edinburgh Postnatal Depression Scale at your 6-week check and answer honestly.'),
  ('tell-your-birth-story-m1', 'emotional_wellness'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Tell Your Birth Story', 'Tell one trusted person your birth story in your own words, without performing okayness. Let them listen without advising or fixing. If your birth was traumatic or not what you expected, this matters more, not less. The story needs to leave your body through words before it can settle.', 30, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: write it down if you haven''t. Month 6: a birth story letter to yourself.'),
  ('letting-people-help-m1', 'emotional_wellness'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Letting People Help', 'List 5 specific things you will accept help with this week — cooking, laundry, night feeds, older children. Share the list. Most new mothers struggle to receive help even when it''s offered, because accepting feels like failing. It isn''t. Help in this window is the difference between recovery and depletion.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: extend the list and practise asking rather than waiting to be offered.'),
  ('saying-not-yet-to-visitors-m1', 'emotional_wellness'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Saying Not Yet to Visitors', 'You are allowed to limit visitors. A simple message works: ''We''re resting and establishing feeding — we''ll welcome visitors from [date].'' Excessive early visitors disrupt rest and create social obligation for a woman who has just been through a major physical event.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: selectively expand — one trusted visitor per week, on your terms.'),
  ('how-am-i-feeling-today-m1', 'emotional_wellness'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'How Am I Feeling Today', 'Each evening write or voice-note one sentence about how you feel. Not how the baby is — how you are. ''I felt lost this morning but calmer by evening.'' One honest sentence a day is both a mood record and a validation practice.', 2, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: read back the month''s sentences. The arc is usually more hopeful than the individual days felt.'),
  ('skin-to-skin-time-m1', 'mother_baby_bonding'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Skin-to-Skin Time', 'Baby bare-chested on your bare chest, covered with a warm cloth. As many hours as the day allows. The research here is as close to certain as developmental science gets: temperature regulation, feeding establishment, cortisol reduction in both of you, and the deepest foundation of secure attachment.', 60, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue throughout. These quiet hours become rarer as baby grows more mobile — make them abundant now.'),
  ('talk-to-your-baby-m1', 'mother_baby_bonding'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Talk to Your Baby', 'Your baby has heard your voice for roughly 5 months in the womb. Talk to them now — narrate, sing, read aloud, at close range. Not performatively. Your specific voice and rhythm is the most familiar thing in their new world. The continuity between womb and world is your voice.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: baby begins orienting to your voice specifically. Month 3: they respond differently to yours than to any other.'),
  ('looking-into-baby-s-eyes-m1', 'mother_baby_bonding'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Looking Into Baby''s Eyes', 'Hold baby 20–25cm from your face — exactly their clearest range in week 1. Look at them without trying to teach or stimulate anything. Mutual gaze between mother and newborn produces oxytocin in both simultaneously. This isn''t preparation for a milestone. This is the relationship happening.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: baby begins to smile. Month 3: baby initiates the gaze. Reciprocate every time.'),
  ('bedtime-song-m1', 'mother_baby_bonding'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Bedtime Song', 'Choose one song — a lori from your childhood, a folk song, anything that means something to you — and sing it every evening. Same song, every night. You''re creating a sound anchor that will regulate your baby''s nervous system for years, and passing on a piece of your own inheritance.', 10, 'evening'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. By month 6 baby settles when it begins. By month 12 it''s a shared memory.'),
  ('who-wakes-up-when-m1', 'couple_connection'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Who Wakes Up When', 'Before the first night home, agree in writing who takes which window. Sample: 9pm–1am one parent, 1am–6am the other. The specific structure matters less than having one. ''We''ll figure it out'' is the sentence most responsible for postpartum resentment.', 15, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: review and adjust — what works in week 1 often needs recalibrating by week 4.'),
  ('we-re-in-survival-mode-m1', 'couple_connection'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'We''re in Survival Mode', 'Say it to each other once, explicitly: ''We are in survival mode. This is temporary. We are doing this together.'' Couples who name the season survive it better than those who perform normalcy. Survival mode has different rules — lower expectations, higher tolerance, more practical support.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: revisit — is there breathing room appearing yet?'),
  ('our-help-word-m1', 'couple_connection'::mother_activity_category, 1, 'all'::mother_activity_relevance, 'Our Help Word', 'Agree on one word or phrase meaning ''I am at my limit and need relief right now, no questions asked.'' When used, the other person takes over immediately. No negotiation, no ''but I''m also tired.'' It''s a circuit breaker, not a competition.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. Its value is in existing, not in frequent use.'),
  ('2-minute-check-in-m1', 'couple_connection'::mother_activity_category, 1, 'all'::mother_activity_relevance, '2-Minute Check-In', 'Once a day ask each other one question that isn''t about the baby: ''How are YOU?'' Wait for the real answer. 2 minutes each. In month 1 this is the entire relationship maintenance practice — and that is enough.', 4, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: add a second question. Month 4: extend to the nightly 5-minute debrief.'),
  ('doctor-visit-bring-questions-m2', 'physical_recovery'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Doctor Visit — Bring Questions', 'Attend your 6-week check with questions written down. Am I cleared for pelvic floor work? Light exercise? Is my healing normal? Is my bleeding pattern normal? I''ve been feeling [describe honestly] — is that within expected range? Most women leave this appointment without asking anything. The time is yours.', 15, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: act on the clearances. Book a women''s health physiotherapist if recommended.'),
  ('gentle-squeeze-exercise-m2', 'physical_recovery'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Gentle Squeeze Exercise', 'Lie comfortably. Imagine lifting and closing the pelvic floor. Hold 3 seconds, release 6. 5 reps, twice daily. Pregnancy affects the pelvic floor regardless of how you delivered, so this matters for every mother. If you feel pain, stop and see a women''s health physiotherapist before continuing.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: 5-second holds. Month 4: 8 seconds. Month 5: elevator lifts and quick flicks.'),
  ('short-walk-m2', 'physical_recovery'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Short Walk', 'Start with a 10-minute flat walk daily. Outdoors where possible — sunlight, air, and gentle stimulation all support recovery. This month''s goal is simply the daily walk, not pace or distance.', 10, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: 15–20 min. Month 4: 25 min with mild pace variation.'),
  ('fix-your-feeding-posture-m2', 'physical_recovery'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Fix Your Feeding Posture', 'Most women develop neck and upper back pain from weeks of hunched feeding. Use a firm pillow to bring baby to breast height rather than leaning down. After each feed: 5 backward shoulder rolls and a 20-second chest opener. Consider one session with a lactation consultant or physio if pain affects your feeding comfort.', 5, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. This is one of the most preventable and most ignored postpartum physical issues.'),
  ('neck-and-shoulder-stretch-m2', 'physical_recovery'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Neck and Shoulder Stretch', 'Drop your right ear toward your right shoulder, hold 20 seconds. Chin to chest, roll slowly left, hold 20 seconds. 5 backward shoulder rolls. Then clasp hands behind your back and squeeze the shoulder blades for 10 seconds. Do this after any prolonged feeding session.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue through month 12. Increase frequency during growth spurts when feeding is more intense.'),
  ('cat-cow-stretch-m2', 'physical_recovery'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Cat-Cow Stretch', 'On all fours. Inhale — drop belly, lift chin and tailbone. Exhale — round the spine toward the ceiling. 8 slow rounds. This restores spinal mobility and reawakens the deep stabilisers after weeks of stillness.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: add thread-the-needle rotation. Month 4: add bird-dog from all fours.'),
  ('gentle-scar-care-first-try-m2', 'physical_recovery'::mother_activity_category, 2, 'caesarean'::mother_activity_relevance, 'Gentle Scar Care — First Try', 'Once the wound is fully closed and your doctor has cleared it at the 6-week check, begin very lightly: touch the skin just above and below the scar with dry fingertips and move the skin, not the scar itself, in gentle horizontal circles. 1 minute daily. Numbness, sensitivity, or feeling nothing at all are all normal. The goal this month is only to establish the habit.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: begin actual scar tissue mobilisation in 3 directions.'),
  ('squeezes-matter-for-you-too-m2', 'physical_recovery'::mother_activity_category, 2, 'caesarean'::mother_activity_relevance, 'Squeezes Matter for You Too', 'Pregnancy affects the pelvic floor regardless of how you delivered, and this is widely misunderstood by C-section mothers who assume they are exempt. Nine months of carrying a growing uterus loads the pelvic floor whether or not a baby passed through it. Begin gentle contractions after clearance: hold 3 seconds, release 6, 5 reps twice daily.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: 5-second holds. Month 4: elevator lifts. Month 5: quick flicks.'),
  ('move-without-hurting-the-scar-m2', 'physical_recovery'::mother_activity_category, 2, 'caesarean'::mother_activity_relevance, 'Move Without Hurting the Scar', 'Relearn how to move without loading the incision: log roll to get up, bend at the knees rather than the waist, keep objects close to your body when carrying, and exhale on any effort. These patterns protect the healing scar and, once habitual, protect your back for years afterwards.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: patterns should be automatic. Month 6: apply them to heavier loads.'),
  ('mood-check-test-m2', 'emotional_wellness'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Mood Check Test', 'A 10-question self-assessment, standard at the 6-week check. Take it honestly. A score of 10 or above warrants a conversation with your doctor. PPD is not a character failure — it is a medical condition with excellent treatment outcomes. If you aren''t offered the screen, ask for it.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: take it again. PPD can emerge or peak at 3–4 months, not only in the first weeks.'),
  ('becoming-a-mother-named-m2', 'emotional_wellness'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Becoming a Mother, Named', 'Write for 10 minutes. Who was I before? Who am I becoming? What feels lost? What feels gained that I didn''t expect? Matrescence — the developmental transition into motherhood — is as significant as adolescence and almost entirely culturally unacknowledged. Naming it reduces the sense that something is wrong with you.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: return to what you wrote. Month 6: full identity map exercise.'),
  ('how-much-sleep-am-i-missing-m2', 'emotional_wellness'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'How Much Sleep Am I Missing', 'Write down your sleep for 7 days: total hours, longest unbroken stretch, number of interruptions. Compare against 49 hours. Most mothers at month 2 run a 15–25 hour weekly deficit. Seeing the number isn''t depressing — it''s validating. Your fog and reactivity are the predictable result of severe deprivation, not weakness.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: use the data to make one structural change to sleep.'),
  ('one-good-thing-today-m2', 'emotional_wellness'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'One Good Thing Today', 'Each day, name one thing that gave you genuine pleasure. It can be tiny — the first sip of chai, five minutes of sun, a song that came on unexpectedly. Write it down. Actively hunting for joy rather than waiting for it is a learnable skill, and particularly effective during sleep deprivation.', 2, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. The joys become less surprising and more deliberate.'),
  ('baby-s-first-real-smile-m2', 'mother_baby_bonding'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Baby''s First Real Smile', 'Between weeks 4–8 your baby produces their first genuine social smile, in response to a human face. Mirror it back immediately and warmly. This is the first deliberate social communication your child has ever made. Your response teaches them: my signals produce responses, I matter.', 5, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: smiles become more frequent and more socially targeted.'),
  ('tummy-time-together-m2', 'mother_baby_bonding'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Tummy Time Together', 'Lie face-down alongside baby during tummy time. Get to their level. Your face in front of them at the same height — not looming from above — is the strongest possible motivation to lift their head.', 5, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: increase to 20 min total daily. Month 4: baby begins pivoting.'),
  ('copy-baby-s-sounds-m2', 'mother_baby_bonding'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Copy Baby''s Sounds', 'When baby makes any sound, respond with the same sound, then pause. This is serve-and-return at its earliest. Even at month 2 babies often repeat the sound after you respond. That repetition is the beginning of language, and the structure you create now becomes the template for every conversation they''ll have.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: hold the pause 10 full seconds. Month 4: babble becomes more consonant-rich.'),
  ('talk-through-every-task-m2', 'mother_baby_bonding'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Talk Through Every Task', 'Running commentary on everything: ''Now the left arm through the sleeve. Baayi haath. This is your vest — naram kapda.'' Baby isn''t understanding words yet, but they''re cataloguing the sounds, rhythms, and patterns of your language. Every narrated routine is language architecture.', 0, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. Month 6: add questions and pauses.'),
  ('check-the-night-plan-m2', 'couple_connection'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'Check the Night Plan', 'At the 4-week mark, review the structure you agreed in month 1. What''s working? Who is more depleted? Adjust. A structure that worked in week 1 often needs recalibrating by week 4 as baby''s pattern shifts. Adjust proactively rather than at breaking point.', 15, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: second review. Month 4: revisit as baby''s sleep evolves.'),
  ('5-minute-check-in-m2', 'couple_connection'::mother_activity_category, 2, 'all'::mother_activity_relevance, '5-Minute Check-In', 'Extend month 1''s daily check-in to 5 minutes and add a second question: one high, one hard. These two questions nightly are the minimum viable relationship maintenance for this period. They keep the emotional door open when exhaustion would otherwise close it.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: add one specific appreciation. Month 6: full nightly debrief.'),
  ('one-kind-surprise-a-week-m2', 'couple_connection'::mother_activity_category, 2, 'all'::mother_activity_relevance, 'One Kind Surprise a Week', 'Once a week each partner does one specific unasked thing for the other. Not chores — something that communicates care. A warm drink brought over. A lie-in on Saturday. Sitting beside them during the difficult feed. Small, consistent, unasked acts maintain the relationship when grand gestures aren''t possible.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. By month 6 this becomes more reciprocal and less survival-driven.'),
  ('longer-squeeze-holds-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Longer Squeeze Holds', '5-second holds, 10 reps, twice daily. Make sure you aren''t holding your breath during contractions — a common error that increases intra-abdominal pressure rather than reducing it. Each contraction should feel like a lift from below, not a squeeze from outside. If you still feel nothing, see a women''s health physio.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: 8-second holds. Month 5: elevator lifts in 3 graduated levels.'),
  ('deep-tummy-squeeze-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Deep Tummy Squeeze', 'Lie on your back, knees bent. On the exhale, gently draw the lower belly inward and upward — not sucking in, but a slow controlled engagement from the deepest layer. Hold 5 seconds. Release fully on the inhale. 10 reps. This is the muscle that must be restored before any other core work is safe.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: progress to dead bugs. Month 5: bird-dog extensions.'),
  ('hip-lift-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Hip Lift', 'Lie on your back, knees bent, feet flat. Exhale, engage the pelvic floor gently, lift hips to a straight line from knees to shoulders. Hold 2 seconds. Lower slowly. 10 reps. This is the first activity that goes beyond breathing and walking — the start of rebuilding the posterior chain.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: single-leg bridges. Month 5: resistance band above knees.'),
  ('20-minute-walk-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, '20-Minute Walk', 'A 20-minute flat walk daily is appropriate for most women by month 3. Focus on posture: shoulders back, head up, arms swinging. Walking remains the most underrated postpartum exercise — cardiovascular training, endorphins, and better sleep, with no pelvic floor risk at this intensity.', 20, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: 25 min with 2 min brisker. Month 5: 30 min with intervals.'),
  ('wall-stand-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Wall Stand', 'Stand with your back against a wall, heels 5cm out, flatten your back against it. Slowly slide arms upward in a snow-angel motion, keeping contact throughout. 10 reps. Most mothers find they can''t fully flatten their back — that gap is exactly what this closes.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: add a resistance band. Month 5: standing resisted shoulder work.'),
  ('hip-stretch-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Hip Stretch', 'Half-kneel with one knee down, opposite foot forward. Shift weight forward gently until you feel a stretch at the front of the back hip. Hold 30 seconds each side. Relevant for every mother — pregnancy shortens the hip flexors regardless of delivery route, and prolonged sitting during feeding compounds it.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: add arms overhead. Month 5: add rotation toward the front knee.'),
  ('evening-oil-rub-m3', 'physical_recovery'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Evening Oil Rub', 'A shorter abhyanga as an evening ritual: 10 minutes of warm oil on legs and feet, sitting on the edge of the bed. Sesame or coconut. Both a continuation of traditional recovery practice and a nervous system signal that the day is ending — a predictable moment of self-care that costs almost no energy.', 10, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue through month 12 and beyond. This is a permanent wellbeing asset.'),
  ('scar-massage-3-directions-m3', 'physical_recovery'::mother_activity_category, 3, 'caesarean'::mother_activity_relevance, 'Scar Massage — 3 Directions', 'With two fingertips, move the skin at and around the scar in three directions: side to side, up and down, and diagonally. 30 seconds each, 2 minutes total, daily. The scar is still actively maturing for another 12–18 months, and this work now prevents the adhesions that cause discomfort and restricted movement later.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: add deeper pressure. Month 6: expand to the surrounding fascia.'),
  ('hip-stretch-extra-important-m3', 'physical_recovery'::mother_activity_category, 3, 'caesarean'::mother_activity_relevance, 'Hip Stretch — Extra Important', 'Half-kneel, one knee down, opposite foot forward, shift weight forward gently. Hold 30 seconds each side. Every mother benefits from this, but C-section mothers usually have more pronounced tightness from the surgical position and reduced early walking. Prioritise it.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: arms overhead for a deeper stretch. Month 5: add rotation toward the front knee.'),
  ('map-the-numb-spot-m3', 'physical_recovery'::mother_activity_category, 3, 'caesarean'::mother_activity_relevance, 'Map the Numb Spot', 'Map the area of numbness around your scar with a light fingertip touch, and note where sensation begins and ends. Numbness above the scar is extremely common and rarely explained to women in advance. Tracking the area over months lets you see it shrinking, which it usually does — slowly, and often incompletely.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: remap and compare. Month 9: begin active desensitisation if numbness persists.'),
  ('mood-check-again-m3', 'emotional_wellness'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Mood Check Again', 'PPD doesn''t only occur in the first weeks — it can emerge or peak at 3–4 months, when the initial support has withdrawn but the exhaustion has accumulated. Retake the Edinburgh scale. A score of 10+ warrants contacting your doctor. You don''t have to be in crisis to deserve support.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: final re-screen. If symptoms persist past 5 months, seek professional support.'),
  ('planning-to-go-back-to-work-m3', 'emotional_wellness'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Planning to Go Back to Work', 'If you''re returning to work in months 3–6, start thinking now rather than the week before. List what needs to be in place: childcare, feeding plan, workplace flexibility, mental preparation. Write the list without deciding anything. The thinking time significantly reduces the anxiety of the transition itself.', 15, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: one concrete arrangement per week. Month 5: childcare confirmed and trialled.'),
  ('who-am-i-now-m3', 'emotional_wellness'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Who Am I Now', 'Write for 10 minutes. What have I kept of who I was? What feels gone? What has surprised me about who I''m becoming? Three months in, the initial adrenaline has worn off and the longer reality is settling. The emotions that emerge now are more durable and more informative than the first-week ones.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: full identity map. Month 12: year-one identity review.'),
  ('what-s-bugging-me-m3', 'emotional_wellness'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'What''s Bugging Me', 'Write 5 specific resentments from this week. ''I resent that no one asks how I am.'' ''I resent that my body isn''t mine right now.'' Naming specific resentments is the first step toward either addressing them or consciously accepting them. Unnamed resentment accumulates and corrodes.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: share one with your partner as a need — ''I need...'' rather than ''I resent...'''),
  ('call-an-old-friend-m3', 'emotional_wellness'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Call an Old Friend', 'Contact one friend from your life before the baby — specifically not a fellow parent. A call, a coffee. Talk about something entirely unrelated to babies. Adults who maintain non-parent connections through early parenthood have measurably better wellbeing outcomes. The effort is disproportionate to the reward, and worth it.', 45, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: make it monthly. Month 7: rejoin one regular social activity.'),
  ('marking-40-days-m3', 'emotional_wellness'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Marking 40 Days', 'If you observed the chilla, the 40-day mark deserves acknowledgement. It isn''t the end of recovery — physical recovery takes 12 months — but it is the end of the most protected period. Mark it: a meal you''ve been missing, a first outing, a conversation with the women in your family about their own chilla.', 30, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: expand activity and social engagement gradually. Month 6: full re-entry.'),
  ('back-and-forth-talk-game-m3', 'mother_baby_bonding'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Back-and-Forth Talk Game', 'During a calm alert moment, respond to every baby sound or movement, then pause and wait for theirs. Count the back-and-forth turns. A 3-month-old sustains 3–5. This is the most evidence-dense activity in early childhood development — thousands of these exchanges form the architecture for language and executive function.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: 5–7 turns. Month 6: up to 10. Note the growing sophistication.'),
  ('black-and-white-card-game-m3', 'mother_baby_bonding'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Black and White Card Game', 'Hold black-and-white cards or a B&W book 20–25cm away and move slowly left to right. At 3 months the tracking is far more deliberate and sustained than at month 1. You aren''t drilling flashcards — you''re providing the visual contrast that early visual cortex development specifically requires.', 5, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: baby tracks a moving person rather than a card.'),
  ('read-out-loud-m3', 'mother_baby_bonding'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'Read Out Loud', 'Read anything to your baby — a novel, a newspaper, a recipe. The vocabulary density of adult text is richer than children''s books. Baby isn''t learning words yet; they''re mapping the sound architecture of your language. In a dual-language home, read in both. Highest value, lowest effort bar. Just read.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: move to picture books. Month 6: point to images while naming them.'),
  ('how-are-we-doing-really-m3', 'couple_connection'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'How Are We Doing, Really?', 'Schedule 20 minutes — not at 11pm when exhausted — with one agenda item: how are we actually doing as a couple? Not who does more night feeds. How is the relationship? What''s been hardest? Most couples haven''t had this conversation by month 3. Having it imperfectly is far better than not having it.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: second conversation. Month 6: weekly check-in begins.'),
  ('what-alone-time-do-i-need-m3', 'couple_connection'::mother_activity_category, 3, 'all'::mother_activity_relevance, 'What Alone Time Do I Need', 'Each partner writes down: how much alone time do I need weekly, what does it look like, what makes it possible? Share the lists. Make one concrete arrangement. Most resentment about individual space comes not from a lack of goodwill but from the absence of an explicit conversation.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: review whether it''s actually happening. Month 9: renegotiate.'),
  ('dead-bug-stretch-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Dead Bug Stretch', 'Lie on your back, arms toward the ceiling, hips and knees at 90 degrees. Slowly lower one arm overhead and the opposite leg toward the floor while exhaling. Return slowly. 8 each side. This is the first real core exercise of postpartum recovery — it builds deep stability without loading the midline.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: 12 each side. Month 6: add light resistance band around feet.'),
  ('lift-like-a-lift-elevator-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Lift Like a Lift (Elevator)', 'Imagine the pelvic floor as a lift with 3 floors. Contract to floor 1, then 2, then 3. Hold at the top 8 seconds. Descend level by level. 10 reps. This builds finer neuromuscular control than standard Kegels — the difference between gross and fine motor skill in the pelvic floor.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: add 10 quick flicks after each set for fast-twitch training.'),
  ('walk-fast-and-slow-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Walk, Fast and Slow', '25 minutes: 5 easy, then alternate 3 minutes brisk with 2 minutes easy twice, then 5 easy. The brisk intervals begin cardiovascular rehabilitation without the pelvic floor impact of running. Build the aerobic base at this pace before building intensity.', 25, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 5: 4-minute brisk intervals. Month 6: assess readiness for gentle jogging.'),
  ('bird-dog-stretch-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Bird-Dog Stretch', 'On all fours, extend one arm forward and the opposite leg back simultaneously. Spine absolutely neutral — no sagging, no rotation. Hold 3 seconds. 10 each side. The anti-crunch. Builds deep spinal stabilisers and gluteus medius without loading the midline.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 5: add a 1-second pause at full extension. Month 6: progress to modified plank.'),
  ('one-leg-hip-lift-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'One-Leg Hip Lift', 'Lie on your back, knees bent. Extend one leg. Exhale and lift the hips using only the grounded leg. Hold 2 seconds. 10 each side, 2 sets. Significantly harder than the bilateral version and directly trains the pelvic stability needed for walking, stairs, and carrying.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 5: resistance band above the working knee. Month 6: resisted band bridges.'),
  ('stretchy-band-arm-workout-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Stretchy Band Arm Workout', 'Band around a door handle. Rows: pull hands toward the lower ribs, elbows close, 15 reps. Bicep curls, 15. Shoulder press, 12. The first upper-body resistance work of recovery. Upper body strength atrophied significantly during the sedentary newborn weeks, and rebuilding it also restores the posture that feeding has bent.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 5: add bent-over rows and lateral raises. Month 6: heavier band.'),
  ('what-my-body-has-done-m4', 'physical_recovery'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'What My Body Has Done', 'Write 3 things your body has done in 4 months that are remarkable. Not aesthetic — functional. It grew a human. It delivered one. It''s producing food. It recovered from major physical trauma. Most postpartum body image work focuses on returning to a previous shape; this focuses on what the shape accomplished.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Return at month 8 and month 12 and compare what you write.'),
  ('scar-massage-deeper-now-m4', 'physical_recovery'::mother_activity_category, 4, 'caesarean'::mother_activity_relevance, 'Scar Massage — Deeper Now', 'Progress to firmer mobilisation: two fingertips with meaningful but not painful pressure in all three directions, plus gentle circular work directly on the scar. 3 minutes daily. Include the tissue 2cm around the scar — fascia adheres over a wider area than the visible line. This month''s work directly determines how the scar feels at month 12 and beyond.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: expand the radius to the full surrounding fascia. Month 8: use a smooth rolling object.'),
  ('reconnect-with-your-tummy-muscles-m4', 'physical_recovery'::mother_activity_category, 4, 'caesarean'::mother_activity_relevance, 'Reconnect With Your Tummy Muscles', 'The abdominal muscles were cut through and the nerve supply disrupted, so reconnecting to them takes deliberate work that vaginal delivery mothers usually don''t need. Lie on your back, place a hand on your lower belly, and try to draw it gently inward on the exhale. If you cannot feel it engaging, that is normal at this stage and worth persisting with.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: should be able to feel engagement. Month 6: progress to dead bugs and bird dogs.'),
  ('scar-and-bad-posture-link-m4', 'physical_recovery'::mother_activity_category, 4, 'caesarean'::mother_activity_relevance, 'Scar and Bad Posture Link', 'C-section scar tightness pulls the pelvis into an anterior tilt and can create lower back pain that seems unrelated to the surgery. Check: stand side-on to a mirror. Is your lower back excessively curved? If so, combine daily scar mobilisation with the hip flexor release — treating the scar often resolves the back pain.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: reassess posture. Month 8: if unresolved, a physio can treat the scar-posture link directly.'),
  ('mood-check-at-4-months-m4', 'emotional_wellness'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Mood Check at 4 Months', 'PPD peaks for many women at 3–4 months, not 3–4 weeks. Retake the Edinburgh scale. If you''re struggling — persistent low mood, loss of pleasure, anxiety, rage that feels disproportionate, difficulty bonding — tell your doctor. PPD is underdiagnosed at this stage precisely because the initial heightened concern has faded.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'If your score is 10+, seek support this week, not next month.'),
  ('get-ready-to-go-back-to-work-m4', 'emotional_wellness'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Get Ready to Go Back to Work', 'One concrete arrangement per week: childcare trial run, milk storage plan, conversation with your employer, handover note drafted. Breaking re-entry into micro-steps makes each manageable. Acknowledge that this transition is genuinely difficult in both its logistical and emotional dimensions.', 20, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: childcare confirmed and trialled. Month 6: debrief what''s harder and what''s better.'),
  ('3-lines-every-morning-m4', 'emotional_wellness'::mother_activity_category, 4, 'all'::mother_activity_relevance, '3 Lines Every Morning', 'Before picking up your phone, write 3 lines. One thing you''re grateful for. One feeling from yesterday. One intention for today. The constraint is the practice — 3 lines is achievable every single day. Keep the journal beside the bed so the barrier to starting is zero.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: add a 4th line — one thing I need today. Month 9: share the need with your partner.'),
  ('one-hour-just-for-me-m4', 'emotional_wellness'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'One Hour Just for Me', 'Schedule and protect one hour this week entirely for yourself. Not errands. Something that connects you to yourself outside the mother role: a show you care about, a book, a walk with headphones, a coffee shop alone. You were a full person before. Maintain that personhood actively.', 60, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: two hours weekly. Month 7: a non-negotiable weekly solo activity.'),
  ('name-the-feeling-m4', 'emotional_wellness'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Name the Feeling', 'When you feel something strong — irritation, grief, unexpected joy, resentment, overwhelm — name it within 60 seconds, aloud or in writing. ''I am feeling overwhelmed right now.'' Named emotions carry less neurological charge than unnamed ones; labelling activates the prefrontal cortex and dampens amygdala reactivity. This is a practised skill.', 2, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: add ''and what I need right now is...''. Month 6: share the named emotion with your partner.'),
  ('longer-babble-chat-m4', 'mother_baby_bonding'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Longer Babble Chat', 'A dedicated 15-minute session: respond to every sound with a vocal turn, hold the pause 10 full seconds. By month 4 the consonant repertoire is expanding — ba-, da-, ma- emerging. These aren''t words yet, but they''re the exact phonemes first words will be built from.', 15, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: imitate new consonants baby hasn''t produced. Month 6: attach labels to sounds.'),
  ('explore-an-object-m4', 'mother_baby_bonding'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Explore an Object', 'Offer 3–4 simple household objects — a wooden spoon, a metal cup, a cloth, a plastic bottle. Let baby handle each without directing. Observe: which do they mouth, bang, pass between hands? At 4 months babies are beginning to understand objects as having consistent properties. Your observation without intervention is the gift.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: add cause-effect objects. Month 6: hiding and finding games.'),
  ('picture-book-time-m4', 'mother_baby_bonding'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Picture Book Time', 'Introduce board books with 1–2 high-contrast images per page. Read slowly: point, name, pause. You aren''t drilling vocabulary — you''re introducing that images represent real things, and that reading is shared, pleasurable, and associated with closeness. That association is being formed right now.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: add animal sounds. Month 6: ''Kahaan hai billee?'' — pointing games.'),
  ('5-minute-nightly-chat-m4', 'couple_connection'::mother_activity_category, 4, 'all'::mother_activity_relevance, '5-Minute Nightly Chat', 'Formalise it: one high, one hard, one appreciation for your partner. 5 minutes before sleep. This simple structure done nightly is the most sustainable relationship maintenance available in the first year. It requires almost no energy and produces a consistent thread of connection through weeks when depth is impossible.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: add ''one thing I need from you this week.'' Month 9: full weekly check-in.'),
  ('date-night-at-home-m4', 'couple_connection'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'Date Night at Home', 'After baby''s asleep: set the table, cook or order deliberately, phones away for 60 minutes. You don''t need to go out to have a date — you need intention, novelty, and mutual attention. Month 4 is the first point where this is realistically possible. Don''t wait for the perfect moment.', 60, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: weekly. Month 8: first outing without baby.'),
  ('how-are-we-doing-round-2-m4', 'couple_connection'::mother_activity_category, 4, 'all'::mother_activity_relevance, 'How Are We Doing — Round 2', 'Return to the month 3 conversation. What''s shifted? What''s better? What''s still hard? What do you each need in the next month? This informal quarterly relationship review is more useful than a year of implicitly hoping things improve on their own.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: weekly check-in formalised, with this deeper question kept quarterly.'),
  ('quick-squeezes-m5', 'physical_recovery'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Quick Squeezes', 'After 10 elevator lifts, do 10 quick flicks: contract and release as fast as you can. These train the fast-twitch fibres responsible for continence during a sneeze, cough, or jump. By month 5 most women can feel a clear distinction between the slow holds and fast flicks. If not, see a women''s health physiotherapist.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: add in standing. Month 9: add during walking and jumping.'),
  ('squats-m5', 'physical_recovery'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Squats', 'Feet hip-width, toes slightly out. Lower until the thighs approach parallel, rise through the heels. 15 reps, 2 sets. Functional, compound, appropriate for most women at month 5. Hold baby at chest height as a prop and narrate — ''down, up!'' — their delight makes 2 sets feel shorter.', 10, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 6: pause at the bottom. Month 7: sumo squat. Month 8: add resistance.'),
  ('30-minute-walk-with-fast-bits-m5', 'physical_recovery'::mother_activity_category, 5, 'all'::mother_activity_relevance, '30-Minute Walk with Fast Bits', '30 minutes: 5 warm up, then 4 minutes brisk and 2 minutes easy three times, 5 cool down. A meaningful cardiovascular session. For most women this is the appropriate intensity ceiling before assessing running readiness.', 30, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 6: 5-minute brisk intervals. Month 9: running readiness assessment.'),
  ('cat-cow-and-twist-m5', 'physical_recovery'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Cat-Cow and Twist', '8 cat-cow rounds, then slide one hand under the body and reach through to the other side, following with your gaze. Hold 5 breaths. 5 each side. This thoracic rotation directly counteracts the posture pattern of feeding, carrying, and device use.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: 8-breath holds. Month 7: fixed daily routine item.'),
  ('getting-stronger-step-by-step-m5', 'physical_recovery'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Getting Stronger, Step by Step', 'Weeks 1–2: 3 sets of 10 each. Weeks 3–4: 3 sets of 12, or slightly more resistance. Exercises: glute bridges, bird dogs, dead bugs, band rows, band shoulder press, bicep curls. Progressive overload is the mechanism. Log your sessions — the written record makes progress visible and the practice sustainable.', 20, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 6: add squats and a hip hinge. Month 7: structured 3×/week programme.'),
  ('massage-around-the-scar-m5', 'physical_recovery'::mother_activity_category, 5, 'caesarean'::mother_activity_relevance, 'Massage Around the Scar', 'Work the tissue 3–4cm in all directions from the visible scar. Fascia is a connected web, and adhesions felt at the scar extend into surrounding tissue in ways that affect bladder position, hip flexor tension, and lower abdominal sensation. Use a smooth round bottle or your knuckles for rolling pressure. 4 minutes daily.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: full surrounding fascia work. Month 8: taper to 3×/week as tissue softens.'),
  ('check-the-gap-after-surgery-m5', 'physical_recovery'::mother_activity_category, 5, 'caesarean'::mother_activity_relevance, 'Check the Gap After Surgery', 'Check the midline gap above the navel: two fingers on the midline, lift your head slowly, feel for a gap or tissue that sinks. C-section mothers often have both diastasis and scar restriction together, and each makes the other harder to resolve. If the gap exceeds two finger-widths, see a women''s health physiotherapist before any plank or crunch work.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: recheck. Determine your core progression plan from the result.'),
  ('what-surprised-me-about-myself-m5', 'emotional_wellness'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'What Surprised Me About Myself', 'Write for 10 minutes about what has genuinely surprised you about yourself as a mother in 5 months. The capacity you didn''t know you had. The limits you didn''t expect. The love that arrived differently than you imagined. Five months is enough time for real self-knowledge to have formed. Document it before it becomes assumed.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: full identity map. Month 12: year-one review.'),
  ('one-hour-no-phone-m5', 'emotional_wellness'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'One Hour, No Phone', 'One hour each evening with your phone in another room. This isn''t about productivity. It''s about allowing your nervous system to be genuinely unstimulated — something that almost certainly hasn''t happened in 5 months. The compulsion to check during this hour is itself information about how much load you''re carrying.', 60, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: continue. Month 7: consider extending to 90 minutes.'),
  ('write-down-my-anger-m5', 'emotional_wellness'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Write Down My Anger', '10 minutes, timed. Write every resentment and frustration about this season — the body, the sleep, the loss of freedom, specific people, specific situations. Don''t stop. Don''t edit. Naming specific angers is the first step to processing rather than suppressing them. Destroy the page afterward or keep it — your choice.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: second. Month 11: third. Compare all three at month 12 — the arc is visible.'),
  ('one-goal-just-for-me-m5', 'emotional_wellness'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'One Goal Just for Me', 'Name one thing you want to do in the next 6 months that is yours — not as a mother, not as a partner. A professional, creative, learning, or fitness goal. Write it down. Tell one person. Naming a personal goal and making it social is the first step toward it not being consumed by early parenting.', 15, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: commit to a first step. Month 10: assess and adjust.'),
  ('rolling-games-m5', 'mother_baby_bonding'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Rolling Games', 'Baby is likely rolling or attempting it. Place a toy just out of reach to the side to encourage it. Get down on the floor and roll alongside them — a full adult roll makes babies laugh and motivates them to try. Physical development as play, and your presence on the floor communicates that movement is joyful.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 6: baby rolls confidently. Create floor circuits to navigate.'),
  ('same-book-5-days-m5', 'mother_baby_bonding'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Same Book, 5 Days', 'Choose one book and read it 5 days running at the same time, then introduce a new one. Repetition first, novelty second — this mirrors how language learning actually works. By day 5 baby shows recognition responses (body quieting, extended gaze, anticipatory posture) that were absent on day 1. That''s memory, forming visibly.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: 7 days per book. Month 9: baby turns pages. Month 12: selects books.'),
  ('touch-and-feel-walk-m5', 'mother_baby_bonding'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Touch-and-Feel Walk', 'Carry baby facing outward. Let their hand briefly touch one texture per walk: tree bark, smooth gate metal, a rough wall, a flower. Describe each in 2–3 words as they touch it. The pathway being built is sensation to language to understanding. You''re laying the first layer.', 20, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: full narrated sensory walk daily. Month 9: baby directs the walk by pointing.'),
  ('peek-a-boo-m5', 'mother_baby_bonding'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Peek-a-Boo', 'At 4–5 months babies respond strongly to faces appearing and disappearing — the earliest form of object permanence. Hide behind your hands, reveal with sound and expression. Simple, repeated, enthusiastic. Their delight isn''t just happiness — it''s the neurological reward of a prediction coming true.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: use a cloth. Month 7: extend the delay. Month 9: let baby hide.'),
  ('weekly-us-check-m5', 'couple_connection'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Weekly Us-Check', 'Formalise it: once a week, 20 minutes, baby asleep or with another caregiver. How am I doing? How are you doing? What do we need from each other this week? What''s working? What needs adjusting? This prevents the accumulation of unexpressed needs that becomes resentment. Start now — it''ll still be relevant at month 60.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: add ''what do you appreciate about how I''m parenting?'''),
  ('something-fun-to-plan-m5', 'couple_connection'::mother_activity_category, 5, 'all'::mother_activity_relevance, 'Something Fun to Plan', 'Have one conversation about something 3–6 months ahead that you both want — a short trip, a dinner, a project at home, a festival together. Future-orientation creates hope in the present and re-establishes you as partners in a shared life rather than co-managers of an ongoing emergency.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: make one of these real. Month 10: annual vision conversation.'),
  ('standing-belly-breathing-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Standing Belly Breathing', 'Progress the month 1 foundation to seated, then standing. One hand on the belly, breathe in through the nose so the belly rises, out through pursed lips for 6 counts, 10 breaths. Breathing well in an upright, loaded position is what transfers to real life — lifting, carrying, and exercise.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: coordinate the exhale with every lift and carry throughout the day.'),
  ('squeezes-in-every-position-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Squeezes in Every Position', '10 eight-second holds plus 10 quick flicks, done in four positions across the week: lying, sitting, standing, and squatting. The pelvic floor must work against gravity in real life, so training it only lying down transfers poorly.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: add during walking. Month 10: assess during jumping and running.'),
  ('cat-cow-with-baby-watching-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Cat-Cow With Baby Watching', 'Baby on the mat in front of you. Inhale, drop the belly, lift the chin — make eye contact. Exhale, round the spine toward the ceiling. Peek at them on each cat. 10 slow rounds. Gentle spinal mobilisation for you, face-to-face social interaction for them.', 10, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: add thread-the-needle. Month 8: add bird-dog from all fours.'),
  ('hip-lift-more-reps-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Hip Lift, More Reps', 'Feet flat, exhale, lift hips to a straight line from knees to shoulders. Hold 2 seconds — squeeze the glutes, not the jaw. Lower slowly. 12 reps, 2 sets.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: single-leg. Month 8: resistance band above the knees.'),
  ('wall-stand-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Wall Stand', 'Back against a wall, heels 5cm out, head resting gently back. Slide the arms up the wall in a snow-angel keeping contact throughout. 10 reps. This undoes the forward rounding that feeding, carrying, and phone use create. Do it before the first feed of the day.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: light resistance band. Month 8: 2 sets of 15, then a doorway chest stretch.'),
  ('morning-walk-with-baby-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Morning Walk With Baby', '20 minutes at a pace where you can hold a conversation. Focus on heel-to-toe gait and swinging arms — the posture of the walk matters as much as the pace. This is medicine: cortisol regulation, vitamin D, joint mobilisation, and vestibular input for baby.', 20, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: 30 min. Month 8: 2-minute brisk intervals. Month 10: add inclines.'),
  ('wrist-stretch-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Wrist Stretch', 'Extend one arm, palm up. Gently pull the fingers toward you, hold 20 seconds. Then palm down, hold 20. Wrist circles each direction. Repeat other side. De Quervain''s tenosynovitis is close to epidemic among new mothers — this is both prevention and treatment.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. Increase frequency if wrist pain is present.'),
  ('neck-and-shoulder-stretch-m6', 'physical_recovery'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Neck and Shoulder Stretch', 'Right ear toward right shoulder, 20 seconds. Chin to chest, roll left, 20 seconds. 5 backward shoulder rolls. Clasp hands behind the back, squeeze the shoulder blades, hold 10. Repeat the sequence twice, after any prolonged feeding session.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. Add frequency during growth spurts.'),
  ('bigger-circle-scar-massage-m6', 'physical_recovery'::mother_activity_category, 6, 'caesarean'::mother_activity_relevance, 'Bigger Circle Scar Massage', 'Expand to include tissue 2cm above and below the visible line, plus gently rolling a smooth round bottle over the surrounding area with moderate pressure. 4 minutes total. This is the most impactful window for scar work — the tissue is still highly remodellable and responds well.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: taper to 3×/week as tissue softens. Month 12: monthly maintenance.'),
  ('hip-stretch-deeper-m6', 'physical_recovery'::mother_activity_category, 6, 'caesarean'::mother_activity_relevance, 'Hip Stretch, Deeper', 'Half-kneel with arms overhead and a gentle rotation toward the front knee. Hold 30 seconds each side. The extended version addresses the deeper psoas, which is directly affected by both the surgical position and months of reduced walking. C-section mothers benefit disproportionately from this.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: add a lunge-position variation. Month 10: integrate into a full mobility routine.'),
  ('3-lines-every-morning-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, '3 Lines Every Morning', 'Before the phone: three lines only. One gratitude, one feeling from yesterday, one intention for today. The constraint is intentional — three lines is achievable every day. Keep it beside the bed so the barrier is zero.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: add a 4th — one thing I need today. Month 9: share that need with your partner.'),
  ('letter-about-your-birth-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Letter About Your Birth', 'Write a letter to yourself about your birth — what happened, what it felt like, what surprised you, what you wish had been different. Not for anyone else. Not to be shared. One of the most underused postpartum processing tools, especially for mothers who feel their birth needs explaining. It doesn''t. Write it.', 20, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Return at month 9 to see how your feelings have shifted. Keep it or burn it — your choice.'),
  ('who-i-am-a-map-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Who I Am — A Map', 'On a blank page write ''I am'' in the centre. Around it write every identity you hold — daughter, professional, friend, partner, reader, cook, mother. Notice which feel distant right now. Circle 2 you want to actively nourish this month alongside motherhood. Those 2 matter.', 20, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: update the map. Month 12: final update — compare to month 6. The arc is the insight.'),
  ('lie-down-while-baby-naps-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Lie Down While Baby Naps', 'When baby naps, lie flat in a quiet room. No phone. You do not have to sleep. Being horizontal in silence is restorative even without sleep. Set a gentle 20-minute alarm so you can rest without watching the clock. This is not laziness — it is the biology of recovery.', 20, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Protect this through all 12 months. As physical activity increases, this rest matters more, not less.'),
  ('evening-mood-score-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Evening Mood Score', 'Rate your mood 1 to 10 each evening, and add one sentence on what most affected it. Over 6 weeks the patterns become clearly visible — sleep, exercise, isolation, and social contact all show up in the data. Knowledge reduces self-blame.', 2, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: review 8 weeks of data and identify your 3 strongest mood predictors.'),
  ('no-phone-evening-hour-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'No-Phone Evening Hour', 'One hour each evening — pick a time and defend it — with the phone in another room. Not about productivity. About letting your nervous system be unstimulated and your attention undemanded. A depleted nervous system is not a parenting style; it''s a medical condition.', 60, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: extend to 90 minutes and add one analog activity to replace screen time.'),
  ('one-friend-call-a-week-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'One Friend Call a Week', 'Schedule — don''t wait to feel like it — one 20-minute call with a friend. It doesn''t need to be about motherhood. Talk about anything else. Sustained adult friendship in the early parenting years requires deliberate maintenance. The effort is asymmetric; the return isn''t.', 20, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: meet in person once. Month 10: join or restart a regular social activity.'),
  ('10-minutes-alone-every-day-m6', 'emotional_wellness'::mother_activity_category, 6, 'all'::mother_activity_relevance, '10 Minutes Alone Every Day', 'Once a day, be alone for 10 minutes. Toilet, garden, balcony, bedroom with the door shut — location is irrelevant. This is maintenance, not selfishness. A depleted caregiver cannot give what they don''t have. Protect it with the same certainty as a feed.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: 15 minutes. Month 9: a solo 30-minute walk once a week.'),
  ('gentle-yoga-with-baby-m6', 'mother_baby_bonding'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Gentle Yoga With Baby', 'Baby on the mat in front of you. Five poses, five breaths each: forward fold (face-to-face), child''s pose (at their eye level), seated side stretch, supine twist, savasana with baby on your chest. Restoration and bonding at once — not exercise, not performance.', 15, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: warrior 1 with baby on the hip. Month 8: baby sits independently and becomes an audience.'),
  ('one-feed-fully-present-m6', 'mother_baby_bonding'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'One Feed, Fully Present', 'Once per day: phone down, no podcast. Eyes on baby''s face. Notice how they swallow, how their hands move, when their eyes close. This isn''t a task to optimise — it''s the relationship happening in real time. What you give attention to grows.', 15, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. As baby weans, adapt it to mindful mealtimes together.'),
  ('walk-and-describe-the-world-m6', 'mother_baby_bonding'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Walk and Describe the World', 'Baby facing out. Narrate what you see, smell, and hear. Stop at interesting things — a flower, a gate, a building site — and describe them in 3 words: ''rough, brown, hard.'' Language development for baby, mindfulness practice for you. The simultaneous benefit is not accidental.', 25, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: add one touch experience per walk. Month 9: follow baby''s pointing — they begin directing.'),
  ('evening-song-m6', 'mother_baby_bonding'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Evening Song', 'One song — a lori, a folk song, something that matters to you — sung every evening during bath or the last feed. Same song, same time, every night. Predictability regulates baby. The singing regulates you. This becomes a shared memory.', 10, 'evening'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. By month 8 baby physically settles when it begins.'),
  ('skin-to-skin-nap-m6', 'mother_baby_bonding'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Skin-to-Skin Nap', 'Once a week during a daytime nap, lie with baby on your chest, skin to skin. Both of you rest. Oxytocin up, cortisol down, both nervous systems regulating. This doesn''t stop being effective after the newborn stage — it works all year.', 30, 'during_nap'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue monthly. It gets harder as baby becomes mobile — which is exactly why to prioritise it now.'),
  ('chores-with-baby-worn-m6', 'mother_baby_bonding'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Chores With Baby Worn', 'Wear baby in a carrier for 20 minutes of household tasks. They get vestibular input, warmth, and closeness. You get tasks done and oxytocin. The movement of ordinary housework is excellent proprioceptive input. Carrying does not spoil them.', 20, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Through month 9 as your back allows. Month 9+: progress to a back carry.'),
  ('5-minute-nightly-chat-m6', 'couple_connection'::mother_activity_category, 6, 'all'::mother_activity_relevance, '5-Minute Nightly Chat', 'Before sleep, each partner shares one high and one hard. 5 minutes total. No problem-solving — only sharing. This maintains connection through a season when long conversations are rare. Consistency beats depth: 5 minutes nightly outperforms 2 hours once a month.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: add one specific appreciation alongside the high and hard.'),
  ('weekly-us-check-m6', 'couple_connection'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Weekly Us-Check', '20 minutes weekly, baby asleep or with another caregiver. How am I doing? How are you? What do we need from each other this week? What''s working? What needs adjusting? Keep a running note of agreements. This is the most important weekly meeting you''ll have.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: add ''what do you appreciate about how I''m parenting?'' Month 9: add a 3-month question.');
insert into mother_activities (id, category, month_postpartum, applies_to, title, description, duration_minutes, time_of_day, with_baby, effort_level, progression_notes) values
  ('talk-about-something-else-m6', 'couple_connection'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Talk About Something Else', '10 minutes daily talking about something with nothing to do with the baby. A news story, a show, a memory, a plan, a ridiculous hypothetical. You were full people before you were parents. Keep that alive through deliberate daily practice.', 10, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: add a weekly topic you both research separately and discuss.'),
  ('weekly-date-at-home-m6', 'couple_connection'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Weekly Date at Home', 'One evening a week after baby''s asleep: set the table, light a candle, cook or order deliberately, phones away for 90 minutes. You don''t need to go out. You need intention, novelty, and mutual attention. Environment is secondary.', 90, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: one proper out-of-home date with family covering. Month 10: monthly.'),
  ('say-thanks-at-dinner-m6', 'couple_connection'::mother_activity_category, 6, 'all'::mother_activity_relevance, 'Say Thanks at Dinner', 'Each person names one thing they appreciate about the other — not about parenting, about the person. ''I noticed you stayed calm during the difficult doctor visit.'' Specific, observed, real. This is attachment maintenance for the couple.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: write one down weekly. Month 10: read them together.'),
  ('lift-like-a-lift-harder-m7', 'physical_recovery'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Lift-Like-a-Lift, Harder', 'Three floors up, hold 5 seconds at the top, descend floor by floor. 10 reps. Finer neuromuscular control than standard Kegels. Lay this groundwork now for the functional demands of months 8–12.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: add 10 quick flicks after each set. Month 9: all four positions.'),
  ('dead-bug-harder-version-m7', 'physical_recovery'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Dead Bug, Harder Version', 'Arms toward the ceiling, hips and knees at 90. Lower one arm overhead and the opposite leg while exhaling. Return slowly. 8 each side. Deep core stability, fundamentally different from crunches and precisely what postpartum recovery needs.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: 12 each side. Month 9: light resistance band around the feet.'),
  ('bird-dog-stretch-m7', 'physical_recovery'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Bird-Dog Stretch', 'On all fours, extend one arm and the opposite leg. Hold 3 seconds, spine neutral. 10 each side. The anti-crunch — deep stabilisers without midline loading. Essential for diastasis recovery and safe for every mother.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 8: 1-second pause at full extension. Month 9: slow lateral rotation at extension.'),
  ('squats-holding-baby-m7', 'physical_recovery'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Squats Holding Baby', 'Hold baby facing outward at chest height. Feet hip-width, toes slightly out. Lower until the thighs approach parallel. Rise through the heels. 15 reps, 2 sets. Baby gets a gentle ride, your legs and glutes rebuild. Narrate as you go.', 10, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 8: pause at the bottom. Month 9: goblet squat holding baby more securely.'),
  ('30-minute-walk-fast-and-slow-m7', 'physical_recovery'::mother_activity_category, 7, 'all'::mother_activity_relevance, '30-Minute Walk, Fast and Slow', '30 minutes, with 2 minutes brisk (too fast to sing) at the 10 and 20-minute marks. These brief bursts restore cardiovascular fitness without the pelvic floor load of running. Build the habit before the intensity.', 30, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 8: 3-minute brisk intervals. Month 9: add a gentle incline route.'),
  ('twist-stretch-m7', 'physical_recovery'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Twist Stretch', 'On all fours, slide one hand under the body and reach through, top arm following. Feel the thoracic spine open. Hold 5 breaths. 5 each side. Counteracts seven months of rounding from feeding and carrying.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: 8-breath holds. Make it a daily routine item.'),
  ('full-scar-massage-routine-m7', 'physical_recovery'::mother_activity_category, 7, 'caesarean'::mother_activity_relevance, 'Full Scar Massage Routine', 'Firm pressure in all three directions plus circular work on the scar itself, 3 minutes daily, now including a check for any tight bands running below the scar toward the pubic bone. Those bands are the most common cause of the low-belly pulling sensation that many women describe at this stage and never mention to anyone.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: taper if soft and mobile. Continue daily if any band remains.'),
  ('tummy-exercises-step-by-step-m7', 'physical_recovery'::mother_activity_category, 7, 'caesarean'::mother_activity_relevance, 'Tummy Exercises, Step by Step', 'Because the abdominal wall was surgically divided, progress core loading more conservatively than the general timeline suggests. Dead bugs and bird dogs before any plank, and only progress when you can perform 12 controlled reps with no doming and no pulling at the scar. Slower here produces better outcomes than pushing.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 9: modified plank if 12 clean reps achieved. Month 10: full plank if cleared.'),
  ('one-hour-being-just-me-m7', 'emotional_wellness'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'One Hour Being Just Me', 'Once this week, do something you did before you were a mother. Read for pleasure. Watch something you care about. Cook something elaborate. Go to a shop alone. Walk without purpose. Do it without guilt — or with guilt, but do it anyway. Identity recovery requires practice, not permission.', 60, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: twice weekly. Month 10: a non-negotiable weekly activity that is entirely yours.'),
  ('count-my-missing-sleep-m7', 'emotional_wellness'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Count My Missing Sleep', 'Record your actual sleep for 7 days. Note your longest unbroken stretch. Calculate the weekly deficit against 49 hours. This isn''t about fixing it today — it''s about seeing it clearly. Most mothers badly underestimate the deficit, and the data reduces self-blame for fog and reactivity.', 15, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: use the data to propose one structural change — a partner shift, earlier bedtime, nap arrangement.'),
  ('name-the-feeling-and-the-need-m7', 'emotional_wellness'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Name the Feeling and the Need', 'When you feel something strong, name it within 60 seconds — aloud or written. Then add: ''and what I need right now is...'' The extension turns naming from expressive into functional.', 2, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: begin sharing both parts with your partner in the nightly debrief.'),
  ('dance-with-baby-m7', 'mother_baby_bonding'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Dance With Baby', 'Put on a song you love. Wear baby close. Dance freely and unreservedly in your own home. Baby gets vestibular input, your heartbeat, and the quality of your movement when it''s joyful rather than purposeful. You get to be in your body in a way that isn''t remedial.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 8: vary the music — folk, classical, film songs. Note which produce which responses.'),
  ('15-minutes-of-back-and-forth-play-m7', 'mother_baby_bonding'::mother_activity_category, 7, 'all'::mother_activity_relevance, '15 Minutes of Back-and-Forth Play', 'Devices away. Baby on the mat with 2 toys. Follow their lead entirely for 15 minutes. When they look, look back. When they reach, respond. When they babble, babble back. You do nothing except be fully present and responsive. By wide research consensus, the most important parenting activity available to you.', 15, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. By month 9 baby sustains longer sequences and the exchange visibly deepens.'),
  ('peek-a-boo-new-ways-m7', 'mother_baby_bonding'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Peek-a-Boo, New Ways', 'Object permanence is forming. Hide behind a cloth, a cushion, a door. Return with a different expression or sound each time. The variation tests whether the concept of your return has generalised beyond one script. The anticipatory smile before you reappear is the milestone moment.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 8: 5-second delay before reappearing. Month 9: let baby begin to hide.'),
  ('nightly-chat-plus-a-thank-you-m7', 'couple_connection'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Nightly Chat Plus a Thank You', 'Continue the 5-minute debrief and add one specific observed appreciation. ''I noticed you took the morning feed so I could sleep in.'' Specific over general, always.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: add ''one thing I need from you this week.'''),
  ('check-if-alone-time-is-happening-m7', 'couple_connection'::mother_activity_category, 7, 'all'::mother_activity_relevance, 'Check If Alone Time Is Happening', 'Are the arrangements you made in month 3 and 5 actually happening? Most couples make the agreement and never audit it. Check honestly, and adjust rather than let it quietly lapse.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: renegotiate as needs evolve.'),
  ('check-the-gap-in-your-tummy-m8', 'physical_recovery'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Check the Gap in Your Tummy', 'Lie on your back, knees bent. Two fingers on the midline above the navel. Slowly lift your head. Feel for a gap or soft tissue that sinks under pressure. Normal: narrows to under 2 finger-widths, tissue feels firm. If the gap persists or feels soft, see a women''s health physiotherapist before attempting planks or crunches.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Do this once to determine your core progression plan for months 9–12.'),
  ('easy-plank-on-knees-m8', 'physical_recovery'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Easy Plank on Knees', 'Forearms and knees on the floor, hips level. Hold 10 seconds, rest 30. 5 reps. Watch for any midline doming or coning — if you see it, return to dead bugs for 2 more weeks. This is the safe entry to plank work. Do not rush to a full plank.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 9: full forearm plank if no doming. Month 10: 20–30 second holds.'),
  ('wide-squat-with-baby-m8', 'physical_recovery'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Wide Squat With Baby', 'Feet wide, toes at 45 degrees, baby held close to the chest. Lower into a wide squat, pulse 10 times at the bottom, rise. 3 sets of 10. Targets the inner thighs and gluteus medius — muscles usually underloaded in standard squats and critical for pelvic stability and knee health.', 10, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 9: resistance band above the knees. Month 10: hold baby overhead briefly on the rise.'),
  ('stretchy-band-rowing-m8', 'physical_recovery'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Stretchy Band Rowing', 'Band around a door handle at chest height. Hold one end in each hand, step back. Pull the hands toward the lower ribs, elbows close to the body. 15 reps, 3 sets. Rebuilds the upper back strength that months of feeding posture has progressively suppressed.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 9: heavier band. Month 10: alternate with single-arm rows.'),
  ('35-minute-walk-fast-and-slow-m8', 'physical_recovery'::mother_activity_category, 8, 'all'::mother_activity_relevance, '35-Minute Walk, Fast and Slow', '5 warm up. Then 3 minutes brisk and 2 minutes easy, five times. 5 cool down. Structured cardiovascular rehabilitation without the impact load of running. Build the aerobic base before the intensity.', 35, 'morning'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 9: 4-minute brisk intervals. Month 10: assess readiness for jogging intervals.'),
  ('open-your-chest-lying-down-m8', 'physical_recovery'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Open Your Chest, Lying Down', 'Lie on your back along a rolled blanket running the length of your spine. Arms out to the sides, palms up. Eyes closed. 3–5 minutes. The passive chest opening undoes months of forward posture. Possibly the most underrated recovery tool available.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. Five minutes every evening produces a cumulative postural change.'),
  ('roll-and-press-the-scar-m8', 'physical_recovery'::mother_activity_category, 8, 'caesarean'::mother_activity_relevance, 'Roll and Press the Scar', 'Use a smooth rolling object over the broader area with moderate pressure, plus sustained thumb pressure on any remaining tight points, holding 30 seconds each. 4 minutes total. By month 8 the scar should be noticeably softer than at month 4. If it is not, this is the point to seek physiotherapy rather than continuing alone.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 10: taper to 3×/week if soft. Continue daily if tight.'),
  ('check-the-gap-again-m8', 'physical_recovery'::mother_activity_category, 8, 'caesarean'::mother_activity_relevance, 'Check the Gap Again', 'Recheck the midline. Compare to your month 5 result. C-section mothers frequently see slower diastasis closure because the scar restricts the fascia''s ability to draw back together. If the gap is unchanged since month 5, that is a clear indication for physiotherapy rather than more time.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'If unchanged, book a women''s health physiotherapist this month.'),
  ('thank-your-body-m8', 'emotional_wellness'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Thank Your Body', 'Stand in front of a mirror for 5 minutes. Say aloud or write 3 things your body has done in 8 months that are remarkable. Not things you like about how it looks — what it has done. It grew, delivered, sustained, and held a human being through their most vulnerable phase. That is extraordinary.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Return at month 10 and 12 and compare what you write each time.'),
  ('what-i-miss-from-before-m8', 'emotional_wellness'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'What I Miss From Before', 'Write for 5 minutes about what you miss from your pre-baby life. Don''t censor, don''t feel guilty, don''t explain yourself. Missing things does not mean loving your baby less. It means you were a full person before and still are. Grief and love coexist — that isn''t a contradiction.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: write what you do NOT miss. Month 10: what you''ve gained that surprised you.'),
  ('list-everything-that-s-annoying-me-m8', 'emotional_wellness'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'List Everything That''s Annoying Me', 'Set a timer for 10 minutes. Write every resentment and frustration — your partner, your body, sleep, loss of freedom, endless mess, being touched all day and then touched more. Don''t stop, don''t edit. Naming specific angers is the first step to either addressing them or consciously accepting them.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Share relevant items at your next relationship check-in — as information, not accusation.'),
  ('planning-to-go-back-to-work-m8', 'emotional_wellness'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Planning to Go Back to Work', 'Whether returning in weeks or already back, list what would make it easier: flexible hours, childcare logistics, mental preparation, backup plans. Don''t decide everything yet. Just list. Most mothers find that thinking through options in advance halves the anxiety of the transition.', 20, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: make one concrete arrangement from the list each week.'),
  ('let-baby-lead-the-play-m8', 'mother_baby_bonding'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Let Baby Lead the Play', '30 minutes of floor time with no agenda. No activities, no planned stimulation. Follow baby''s attention entirely. Sit, be available, respond only when invited. Child-initiated play in a responsive environment is the richest developmental context that exists — and it asks less of you than any structured activity.', 30, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: 45 minutes. Notice how play complexity increases week by week.'),
  ('longer-bath-time-m8', 'mother_baby_bonding'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Longer Bath Time', 'Extend bath time to 20 minutes. Slow it down: warm water, simple toys, face-to-face time, singing. Not a hygiene task — one of the most regulated, multi-sensory, calming experiences you can give a baby, and a naturally de-escalating window for you both at day''s end.', 20, 'evening'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month. Rituals accumulate meaning. By month 12 this is a beloved institution.'),
  ('first-time-out-without-baby-m8', 'couple_connection'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'First Time Out Without Baby', 'Plan one 2-hour outing without baby — dinner, a walk, a film, anything. The goal isn''t the activity; it''s the experience of being two people in the world without the parenting role immediately active. Many find this harder emotionally than expected. That difficulty is worth noticing.', 120, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 10: make it monthly. By then it should feel like something you protect, not arrange under pressure.'),
  ('talk-about-next-year-m8', 'couple_connection'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Talk About Next Year', 'One conversation about something 12 months ahead: a holiday, a change at home, a professional plan, a family vision. Future-planning together reactivates the sense of being partners in a shared project — the frame that newborn survival mode suspends entirely.', 30, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 10: create a shared family wishlist or vision document — something tangible you built together.'),
  ('write-a-thank-you-note-m8', 'couple_connection'::mother_activity_category, 8, 'all'::mother_activity_relevance, 'Write a Thank-You Note', 'At the end of this month''s check-in, each partner writes the other a 3-sentence appreciation on paper. Handwritten appreciation is qualitatively different from spoken — it''s kept, re-read, and carries weight that words in an exhausted 11pm conversation cannot.', 15, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 10: collect these and read them all together.'),
  ('full-plank-if-ready-m9', 'physical_recovery'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Full Plank, If Ready', 'If your month 8 diastasis check showed midline closure: full forearm plank on the feet. Hold 15 seconds, rest 45. 5 sets. Check for doming each time. If not cleared, continue the modified plank. Rushing a full plank before the midline closes makes diastasis worse.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 10: 20-second holds. Month 11: 30 seconds. Month 12: side planks.'),
  ('lunges-m9', 'physical_recovery'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Lunges', 'Step forward into a lunge, back knee hovering near the floor. Hold 2 seconds. Drive back through the front heel. 12 each side, 2 sets. Add baby on the hip if comfortable. Rebuilds the single-leg strength that stairs, carrying, and everyday movement demand.', 10, 'anytime'::mother_activity_time_of_day, 'optional'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 10: walking lunges. Month 11: reverse lunges, then add light load.'),
  ('side-leg-lift-m9', 'physical_recovery'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Side Leg Lift', 'Lie on your side, top leg lifts straight to 45 degrees. Pause at the top, lower slowly. 15 each side, 2 sets. Gluteus medius is critical for pelvic stability, knee tracking, and back health — rarely targeted by standard exercises and almost universally weak postpartum.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 10: resistance band above the knees. Month 11: clamshells and side-lying hip circles.'),
  ('head-to-toe-stretch-m9', 'physical_recovery'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Head-to-Toe Stretch', '15 minutes nightly: cat-cow, child''s pose, hip flexor, supported pigeon, supine twist both sides, chest opener on a bolster. By month 9 the acute recovery phase is passing and restoring full range of motion matters as much as building strength. This sequence is a permanent asset, not a temporary routine.', 15, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month, every year. A daily practice, not a phase.'),
  ('arm-and-shoulder-workout-m9', 'physical_recovery'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Arm and Shoulder Workout', 'Band or light dumbbells: shoulder press, bent-over row, bicep curl. 3 sets of 12 each. Upper body strength atrophied during the sedentary newborn period, and rebuilding it also rebuilds the posture that months of feeding and carrying have bent. Both addressed by the same session.', 15, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 10: increase resistance. Month 11: add chest press and tricep extension.'),
  ('wake-up-the-numb-skin-m9', 'physical_recovery'::mother_activity_category, 9, 'caesarean'::mother_activity_relevance, 'Wake Up the Numb Skin', 'If the scar area remains numb or hypersensitive, brush a piece of rough fabric, then a soft cloth, then a fingertip across the scar and surrounding skin, 30 seconds each, three times daily. This re-educates the sensory nerves and is a genuinely trainable, reversible process that most women are never told about.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue until sensation normalises. If numbness persists past 12 months, consult your doctor.'),
  ('ready-to-run-check-tummy-and-scar-m9', 'physical_recovery'::mother_activity_category, 9, 'caesarean'::mother_activity_relevance, 'Ready to Run? Check Tummy and Scar', 'Before running or jumping: 10 jumps, then check for any pulling at the scar, doming along the midline, or lower back pain afterwards. C-section mothers need the abdominal wall to tolerate impact loading, which is a different readiness question from the pelvic floor one. Both must pass.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'If any sign appears, continue strengthening and retest in 6 weeks.'),
  ('letter-to-myself-at-9-months-m9', 'emotional_wellness'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Letter to Myself at 9 Months', 'Write to yourself on the day your baby was born — what you wish that woman had known, what you now know, what has surprised you most about yourself. Milestone documentation and emotional processing in one act. Keep it. It will mean something different at 12 months, and again at 2 years.', 30, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Read alongside your month 12 letter. The distance between them is the story of your year.'),
  ('write-down-my-anger-again-m9', 'emotional_wellness'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Write Down My Anger, Again', '10 minutes, timed. Every resentment, frustration, and rage — your partner, your body, sleep, loss of freedom, specific situations. Don''t stop, don''t edit. Not about being ungrateful — about naming what''s real so it doesn''t accumulate silently. Destroy the page after, or keep it.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 11: third round. At month 12 compare all three — some months are harder, and that''s information, not failure.'),
  ('see-an-old-friend-m9', 'emotional_wellness'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'See an Old Friend', 'Reach out to someone from before the baby — not a fellow parent, someone from the world you inhabited before. Coffee, lunch, a call longer than 10 minutes. Sustained non-parent friendships are among the strongest predictors of postpartum wellbeing across all the research. Worth the effort.', 60, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 11: make it monthly. The friendship may need patient rebuilding — that''s normal.'),
  ('chase-me-crawling-game-m9', 'mother_baby_bonding'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Chase-Me Crawling Game', 'Baby is crawling or close to it. Chase them on all fours. Follow, let them escape, follow again. Full sound effects. The first spatial interaction game — and your cardiovascular system benefits too. Get on the floor and be ridiculous. The ridiculousness is the point.', 15, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 10: add hiding games — hide behind furniture and let baby find you.'),
  ('daily-story-time-m9', 'mother_baby_bonding'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Daily Story Time', 'Same chair, same time, every day — before nap or before bed. Baby in your lap, book in front. You aren''t teaching reading. You''re building the pathways for language and narrative, and the lifelong association of closeness with learning. That association is forming right now.', 10, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue every month, every year. By month 12 baby pulls books off the shelf and brings them to you.'),
  ('how-s-our-team-doing-at-9-months-m9', 'couple_connection'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'How''s Our Team Doing at 9 Months', '45 minutes with a specific agenda: what has been hardest? What have we done well? What do we want to do differently in the next 3 months? A relationship review conducted with kindness instead of defensiveness. The 9-month mark is when fatigue is deepest and naming it together matters most.', 45, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: full-year review.'),
  ('agree-on-alone-time-m9', 'couple_connection'::mother_activity_category, 9, 'all'::mother_activity_relevance, 'Agree on Alone Time', 'Have the conversation explicitly: how many hours does each of you need weekly, doing what, under what conditions? Then make a concrete arrangement. Most couples only have this conversation when someone is already at breaking point rather than as proactive maintenance.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 11: review whether the arrangement is actually happening as agreed.'),
  ('go-back-to-something-you-loved-m10', 'physical_recovery'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Go Back to Something You Loved', 'If you ran, swam, practised yoga, or played a sport before pregnancy, this is the right window to return, modified. Book a session, contact a coach, join a class. Returning to something that is yours — not postpartum-specific — is an identity recovery step as much as a physical one.', 45, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 11: make it weekly. Month 12: decide whether to continue or try something new entirely.'),
  ('strength-workout-3-times-a-week-m10', 'physical_recovery'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Strength Workout, 3 Times a Week', 'A structured programme three times weekly is appropriate for most women now. Focus on squats, hip hinges, rows, shoulder press, and core stability. If you have gym access, work with a trainer for initial programming. At home, bodyweight and a resistance band are sufficient.', 30, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 11: progressive overload — slightly more resistance or 1–2 more reps weekly. Progress is the mechanism.'),
  ('check-your-posture-m10', 'physical_recovery'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Check Your Posture', 'Stand naturally in front of a mirror in side profile. Head forward? Shoulders rounded? Lower back excessively curved? Most mothers have developed significant postural changes from months of feeding, carrying, and device use. If pronounced, 4–6 physiotherapy sessions produce results self-correction cannot.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: reassess. Document what improved and what needs attention in year 2.'),
  ('weekly-outdoor-time-alone-m10', 'physical_recovery'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Weekly Outdoor Time Alone', 'Once a week, physical activity outdoors, alone. Not errands. Movement in the natural world without baby or partner — a walk, jog, cycle, or swim. The cumulative mental health benefit is substantial and sustained, and it''s usually the first thing mothers sacrifice when life gets busy. Protect it first.', 45, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: is the habit established? Commit to 3 more months if not yet automatic.'),
  ('keep-the-scar-soft-m10', 'physical_recovery'::mother_activity_category, 10, 'caesarean'::mother_activity_relevance, 'Keep the Scar Soft', 'If the scar is soft, pale, flat, and mobile with no tight bands, taper to three sessions weekly as maintenance. If any tightness or pulling remains, continue daily. Taper because the tissue has changed, not because ten months have passed — that distinction matters.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: monthly maintenance if fully resolved. Daily if not.'),
  ('lift-heavier-bit-by-bit-m10', 'physical_recovery'::mother_activity_category, 10, 'caesarean'::mother_activity_relevance, 'Lift Heavier, Bit by Bit', 'Ten months on, lifting restrictions are long lifted, but the abdominal wall benefits from deliberate progressive loading rather than a sudden return to heavy tasks. Add load gradually — a full laundry basket, a heavier toddler, shopping bags — while exhaling on effort and watching for any pulling at the scar.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: should be lifting normally with no scar awareness during effort.'),
  ('join-a-group-again-m10', 'emotional_wellness'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Join a Group Again', 'Rejoin or start something with regularity — a book club, running group, monthly dinner, professional network, a new class. Not because you must socialise, but because social isolation beyond the newborn phase is a documented wellbeing risk. Structure makes socialising possible when motivation alone doesn''t.', 60, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: have at least one regular commitment outside the home and outside parenting. Not optional.'),
  ('set-a-body-goal-you-ll-enjoy-m10', 'emotional_wellness'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Set a Body Goal You''ll Enjoy', 'Reframe physical activity as celebration of capability, not correction of change. Set a 3-month goal about capacity — a distance, a strength benchmark, a skill — not a weight or shape. The shift in framing is the shift in your relationship with your body.', 20, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: did you achieve it? Did the goal change? What does that say about your year?'),
  ('what-surprised-me-about-motherhood-m10', 'emotional_wellness'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'What Surprised Me About Motherhood', 'Write about what genuinely surprised you about motherhood — positively and negatively. Not what you expected to feel, but what you actually feel. Most of us are surprised: by the size of the love, by grief for our former lives, by our own capacity, by our own limits.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: compare to your month 6 journal. What has remained, what has changed.'),
  ('furniture-walking-course-m10', 'mother_baby_bonding'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Furniture Walking Course', 'Baby is pulling to stand and cruising. Create a safe circuit: sofa, coffee table, low chair in a loop. Get on the floor and move alongside them, encouraging with real enthusiasm. This is peak physical activity for baby — match their energy. Your delight in their effort matters enormously.', 20, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 11: add outdoor cruising along garden walls or low outdoor furniture.'),
  ('eat-together-m10', 'mother_baby_bonding'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Eat Together', 'Eat the same meal at the same time, baby''s version softer and unseasoned. The shared table is how food culture and mealtime ritual are transmitted. Mealtimes are also the richest daily language environment available — more vocabulary occurs at family mealtimes than in any other daily context.', 20, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 11: baby self-feeds more completely. Let them. Messy eating is learning.'),
  ('monthly-date-out-m10', 'couple_connection'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Monthly Date Out', 'Now monthly and non-negotiable. 2–3 hours away from home as a couple. No parenting discussion for the first 20 minutes at minimum — let it find its way there naturally. Couples who maintain their relationships through the early years make this investment consistently, not occasionally.', 120, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: reflect on what these dates gave you this year. What was your favourite?'),
  ('talk-about-year-two-m10', 'couple_connection'::mother_activity_category, 10, 'all'::mother_activity_relevance, 'Talk About Year Two', 'Start talking about the next year: a second child if relevant, career plans, home changes, travel, family rhythm. Future-orientation together rebuilds the sense of being partners in a shared project — the frame that extended parenting stress erodes without deliberate maintenance.', 30, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: formalise it into something tangible you built together about your shared future.'),
  ('work-toward-a-5km-walk-or-run-m11', 'physical_recovery'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Work Toward a 5km Walk or Run', 'Set a month 12 milestone: walk or run 5 kilometres continuously. Build toward it by extending your longest single session by 10% each week. For most women this is fully achievable by 12 months. Achieving a milestone that is yours — not labelled postpartum — is identity recovery made physical.', 40, 'morning'::mother_activity_time_of_day, 'optional'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: complete the 5km. Celebrate it as the significant achievement it is.'),
  ('strength-workout-written-down-m11', 'physical_recovery'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Strength Workout, Written Down', 'Week 1: 3 sets of 10. Week 2: 3 sets of 12. Week 3: 4 sets of 10 with 5–10% more resistance. Week 4: deload to 3 sets of 8, lighter. This is progressive overload, the mechanism behind all strength adaptation. Log every session — the written record makes progress visible and the practice sustainable.', 30, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: assess what you''ve built and set the next 3-month programme.'),
  ('weekly-outdoor-time-alone-m11', 'physical_recovery'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Weekly Outdoor Time Alone', 'Once a week, outdoors, alone, moving. Not errands. This is the habit most worth carrying into year 2, and the one most easily lost. Protect it before anything else in the week.', 45, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: is it established? Commit to 3 more months if not automatic.'),
  ('check-the-scar-at-11-months-m11', 'physical_recovery'::mother_activity_category, 11, 'caesarean'::mother_activity_relevance, 'Check the Scar at 11 Months', 'At 11 months the scar should be paling and softening. Assess: is it flat and supple, or raised and tight? Any persistent numbness above it? If raised or tight, consult your doctor — silicone gel sheeting and continued massage are the evidence-based options. Full maturation takes up to 24 months, so intervention now still changes the outcome.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: document the condition and bring it to your 12-month appointment.'),
  ('tummy-strength-test-m11', 'physical_recovery'::mother_activity_category, 11, 'caesarean'::mother_activity_relevance, 'Tummy Strength Test', 'Test: can you hold a 30-second forearm plank with no doming, no scar pulling, and no lower back compensation? Can you lift your baby from the floor without bracing awkwardly? These functional benchmarks matter more than any timeline, and passing them means the abdominal wall has genuinely healed rather than merely stopped hurting.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: if either test fails, a physio assessment is warranted.'),
  ('letter-to-your-baby-year-one-m11', 'emotional_wellness'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Letter to Your Baby, Year One', 'Write to your baby about this first year. What you observed in them. What surprised you. What you hope for them. What you want them to know about how you felt becoming their mother. Seal it. Open it on their first birthday.', 30, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Read aloud at the first birthday if you''d like, or keep it private. Either way, write it.'),
  ('write-down-my-anger-third-time-m11', 'emotional_wellness'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Write Down My Anger, Third Time', 'The third quarterly rage journal. 10 minutes, every resentment and frustration. What remains from month 9? What has shifted? The month-by-month comparison is one of the most honest records of postpartum experience available, and most valuable when kept long enough to see the arc.', 10, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: review all three. Note what changed and what remained. Both are meaningful.'),
  ('pick-up-a-goal-for-yourself-m11', 'emotional_wellness'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Pick Up a Goal for Yourself', 'Name one thing you want to do in the next year that is yours — not as a mother, not as a partner. Professional, creative, learning, travel. Write it down. Tell someone. Commit to a first step. One year into parenthood, it''s time to also parent yourself.', 20, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: commit publicly to the first step. Share it with your partner.'),
  ('make-a-sleep-plan-m11', 'emotional_wellness'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Make a Sleep Plan', 'Eleven months in, is sleep improving? If not, what is the structural barrier? Make one concrete change this month — night weaning, sleep training, a shift swap, a catch-up weekend. Chronic deprivation at 11 months warrants a plan, not only acknowledgement.', 20, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: assess whether the change made a measurable difference.'),
  ('see-and-celebrate-first-steps-m11', 'mother_baby_bonding'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'See and Celebrate First Steps', 'First steps usually happen between 9 and 12 months. When they do: film it, call family, celebrate it. But the weeks before — pulling up, cruising, standing unsupported for 3 seconds — are equally remarkable. Notice and celebrate those too. Milestones are a season, not a moment.', 0, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: baby walks. First birthday. The year closes with the most visible milestone of all.'),
  ('let-baby-pick-the-book-m11', 'mother_baby_bonding'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Let Baby Pick the Book', 'Keep books at baby''s level, on a low shelf or in a basket. Let them pull books and bring them to you. This is the beginning of reading choice. Follow their selection without redirecting. Reading the same book for the 40th time isn''t boring — it''s what learning looks like from the inside.', 15, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: they have favourite books. They''ll become yours too. That''s a shared inner life.'),
  ('letter-to-each-other-year-one-m11', 'couple_connection'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Letter to Each Other, Year One', 'Each partner writes the other a letter: what I appreciate about how you''ve been this year as a partner, what I''ve admired about you as a parent, what I want for us next year. Exchange and read together. The emotional equivalent of an annual review, conducted with love and without defensiveness.', 30, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Collect these letters. Re-read them at the 5-year mark.'),
  ('honest-talk-about-closeness-m11', 'couple_connection'::mother_activity_category, 11, 'all'::mother_activity_relevance, 'Honest Talk About Closeness', 'At 11 months: how is physical intimacy, honestly? What has returned, what hasn''t, what feels different. Many couples need explicit permission to acknowledge that this area has required work and isn''t yet where they want it. That acknowledgement is the beginning of addressing it rather than tolerating it in silence.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: acknowledge what changed this year. What do you want to build toward in year 2?'),
  ('finish-the-5km-walk-or-run-m12', 'physical_recovery'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Finish the 5km Walk or Run', 'Complete the goal you set at month 10. Walk or run 5 kilometres continuously. Then set the next 3-month goal. The habit of setting a physical goal and following through — not the specific goal — is what you''re building. That habit belongs in year 2 and every year after.', 45, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Begin a 3-month plan for year 2. Do not lose this momentum.'),
  ('what-my-body-did-this-year-m12', 'physical_recovery'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'What My Body Did This Year', 'Write 5 things your body has done in 12 months. Then: what does it need in the next 12? Rest, strength, flexibility, restoration, adventure, gentleness, challenge — name it specifically. That answer becomes the north star for year 2. A conversation with yourself worth having annually.', 20, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Compare to month 8. What has changed in how you see and speak to yourself?'),
  ('test-your-pelvic-floor-m12', 'physical_recovery'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Test Your Pelvic Floor', 'Functional tests: 10-second holds × 10 without breath-holding, 10 quick flicks, jumping without leaking, brisk walking without urgency. If any test fails at 12 months, see a women''s health physiotherapist. This is not normal — it is common. The distinction matters because it is fully treatable.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Worth repeating annually for life. Pelvic floor fitness is a lifelong asset.'),
  ('make-the-solo-walk-a-habit-m12', 'physical_recovery'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Make the Solo Walk a Habit', 'By month 12 the weekly solo outdoor walk should be non-negotiable. Protect it as fiercely as the baby''s nap schedule. This isn''t a postpartum activity — it''s a permanent mental health practice you discovered this year. Carry it into every year that follows.', 45, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'This habit belongs in year 2 and beyond. Not a phase. Yours.'),
  ('one-year-scar-check-m12', 'physical_recovery'::mother_activity_category, 12, 'caesarean'::mother_activity_relevance, 'One Year Scar Check', 'A full assessment. Is it flat, pale, and supple? Any raised tissue suggesting keloid or hypertrophic scarring? Any tight bands pulling below the scar, felt as low-belly restriction? Any remaining numbness? Document it and bring anything unresolved to your doctor. Full maturation takes up to 24 months — this is midway, not the end.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue monthly massage through months 18–24 if any tightness remains. This is maintenance, not failure.'),
  ('one-year-tummy-test-m12', 'physical_recovery'::mother_activity_category, 12, 'caesarean'::mother_activity_relevance, 'One Year Tummy Test', 'Functional tests specific to this route: a 30-second plank with no doming, lifting from the floor without bracing, coughing without scar pain, and no low-belly pulling during reaching overhead. If any test fails at 12 months, see a women''s health physiotherapist. Surgical recovery genuinely takes longer, and needing more time is not a failure.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Repeat at 18 and 24 months. The abdominal wall continues remodelling throughout year 2.'),
  ('letter-to-myself-year-one-m12', 'emotional_wellness'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Letter to Myself, Year One', 'Write to the woman you were the day before your baby was born. What do you want her to know? What has she carried? What has she discovered about herself? What does she deserve to hear that nobody told her? The most important piece of writing this year. Don''t skip it.', 30, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Read alongside your month 6 birth story letter, one after the other. The arc is the story.'),
  ('who-am-i-now-check-again-m12', 'emotional_wellness'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Who Am I Now — Check Again', 'Return to the month 6 identity map. Which identities have you nourished? Which faded? Draw the new map. The goal isn''t the same identity as before motherhood — it''s a full, integrated identity that includes motherhood without being consumed by it. That''s the work. Note how far you''ve come.', 30, 'during_nap'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Share it with your partner or a trusted friend if you''d like. Or keep it. It''s yours.'),
  ('thankful-for-a-hard-year-m12', 'emotional_wellness'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Thankful for a Hard Year', 'Write a gratitude list — not for what was easy, but for what was hard and what it gave you. The sleepless nights that showed you what you''re made of. The moments of rage that taught you about your needs. The love that surprised you with its size. The hardest gratitude practice there is. Do it anyway.', 15, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Keep this page. Return to it when year 2 is hard.'),
  ('one-promise-to-myself-for-year-2-m12', 'emotional_wellness'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'One Promise to Myself for Year 2', 'Write one non-negotiable self-care commitment for year 2 — the single thing you''ll protect regardless of what happens. Your solo walk. Your journaling. Your workout. Your friend call. One thing, written down, shared with your partner. This replaces the weekly decision of whether to care for yourself.', 20, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Review quarterly in year 2. Renew annually.'),
  ('first-birthday-tradition-m12', 'mother_baby_bonding'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'First Birthday Tradition', 'Design the first birthday thoughtfully — not for the baby, who won''t remember, but for yourselves. A ceremony marking what you have all become this year. A photo, a meal, a letter read aloud, a song. You have raised a human being through their most vulnerable year on earth. That deserves marking with intention.', 120, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Repeat annually. The ceremony accumulates meaning as it grows alongside your child.'),
  ('look-back-at-the-year-s-photos-m12', 'mother_baby_bonding'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Look Back at the Year''s Photos', 'Look through the year''s photos with your baby on your lap. Point, name the people and places, tell the story aloud. They won''t know it yet. But the practice of telling your child their own story — who they were, where they went, who loved them — is one you can continue for their entire life.', 30, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Begin a yearly photo book. One per year. The collection becomes a family archive.'),
  ('story-time-now-a-habit-m12', 'mother_baby_bonding'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Story Time, Now a Habit', 'By month 12 daily reading should be as automatic as feeding. It requires no willpower — only a pile of books at reachable height and 10 minutes. You aren''t teaching literacy. You''re building the architecture for language and narrative, and the association of closeness with curiosity. Those last a lifetime.', 15, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue. This practice has no end date.'),
  ('how-s-our-team-full-year-check-m12', 'couple_connection'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'How''s Our Team — Full Year Check', '90 minutes, without baby, with a prepared agenda. What was the hardest moment for us this year as a couple? What are we most proud of? What do we want to do differently? What do we want to protect in year 2? The most important conversation of the year for your relationship. Schedule it before the birthday.', 90, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Repeat annually. Every year of parenting is a different year of the relationship.'),
  ('date-night-on-the-birthday-m12', 'couple_connection'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Date Night on the Birthday', 'On or near the birthday: dinner, just the two of you. A celebration of what you''ve become as parents and as partners. You survived the hardest year most couples face, and often more than survived. Acknowledge that together, deliberately, with a glass of something good.', 120, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Begin year 2 with the monthly date night as a confirmed, defended commitment.'),
  ('pick-3-habits-to-keep-m12', 'couple_connection'::mother_activity_category, 12, 'all'::mother_activity_relevance, 'Pick 3 Habits to Keep', 'From the year''s practices — nightly debrief, weekly check-in, monthly date — which 3 gave the most value? Write them down. Put them somewhere visible. Commit to them as permanent. The first year tests every relationship; year 2 deserves the same intentional maintenance, and what worked shouldn''t need rediscovering.', 20, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Review quarterly in year 2. Worth renewing explicitly, not merely assuming.'),
  ('warm-sitting-bath-m1', 'physical_recovery'::mother_activity_category, 1, 'vaginal'::mother_activity_relevance, 'Warm Sitting Bath', 'Fill a shallow basin or a sitz bath attachment with comfortably warm water. Sit for 10 minutes, twice daily for the first two weeks. You may add a little turmeric or neem — both have genuine antimicrobial properties and are the traditional choice. Pat dry gently, never scrub. This reduces swelling, promotes healing, and is deeply soothing.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: once daily as healing progresses. Month 3: discontinue and begin perineal massage.'),
  ('ice-pack-down-there-m1', 'physical_recovery'::mother_activity_category, 1, 'vaginal'::mother_activity_relevance, 'Ice Pack Down There', 'In the first 48–72 hours: a clean cloth wrapped around crushed ice or a chilled pad, applied for 10 minutes on, 10 off. Never apply ice directly to skin. Swelling and bruising are normal and ice reduces both. After 72 hours switch to warm sitz baths. Ice first, then warmth — that sequence is correct for soft tissue healing.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Discontinue after 72 hours and transition fully to warm sitz baths.'),
  ('rinse-bottle-routine-m1', 'physical_recovery'::mother_activity_category, 1, 'vaginal'::mother_activity_relevance, 'Rinse Bottle Routine', 'Fill a peri bottle with warm water and rinse the perineal area every time you use the toilet, then pat dry front to back with a clean cloth. Urine on healing tissue stings considerably, and this simple routine makes the first two weeks substantially more comfortable while reducing infection risk.', 3, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue until stitches have healed and urination is comfortable, usually 2–3 weeks.'),
  ('sit-on-a-soft-cushion-m1', 'physical_recovery'::mother_activity_category, 1, 'vaginal'::mother_activity_relevance, 'Sit on a Soft Cushion', 'Sit on a soft cushion or a rolled towel arranged in a horseshoe so there is no direct pressure on the perineum. Feed lying on your side where possible. Direct perineal pressure during the first weeks slows healing and increases pain — positioning is genuinely therapeutic, not just a comfort preference.', 0, 'anytime'::mother_activity_time_of_day, 'yes'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: as healing progresses, sitting becomes comfortable without the cushion.'),
  ('check-your-stitches-m1', 'physical_recovery'::mother_activity_category, 1, 'vaginal'::mother_activity_relevance, 'Check Your Stitches', 'Once daily after washing, check the perineal area with a hand mirror if you''re able. Normal: mild swelling, bruising, stitches gradually dissolving, discomfort that decreases week on week. Abnormal: increasing pain after day 5, foul-smelling discharge, fever above 38°C, or the wound edges separating. If in doubt, call your doctor the same day.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: stitches typically dissolved. Check for scar tightness or a pulling sensation instead.'),
  ('help-for-your-first-toilet-trip-m1', 'physical_recovery'::mother_activity_category, 1, 'vaginal'::mother_activity_relevance, 'Help for Your First Toilet Trip', 'The first bowel movement after a vaginal delivery is a genuine source of anxiety and stitches will not tear. Support the perineum with a clean pad while you go, never strain, and keep fibre and fluids high. Ask about a stool softener if needed. Fear of it causes constipation, which then causes the very straining that hurts.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 2: fear should be resolving. If constipation persists, address it with your doctor.'),
  ('gentle-massage-first-try-m2', 'physical_recovery'::mother_activity_category, 2, 'vaginal'::mother_activity_relevance, 'Gentle Massage — First Try', 'Once the tissue has healed, typically week 5–6, and with your doctor''s clearance: with clean hands and warm oil, gently massage the perineal tissue externally in slow circles for 2 minutes. This begins to address scar tissue and restore elasticity. If any pain is present, see a women''s health physiotherapist rather than continuing through it.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: extend to 4 minutes. Month 4: progress to internal massage with guidance if needed.'),
  ('start-squeezing-doctor-ok-d-m2', 'physical_recovery'::mother_activity_category, 2, 'vaginal'::mother_activity_relevance, 'Start Squeezing, Doctor OK''d', 'After your 6-week check confirms healing, begin gentle contractions: imagine lifting and closing, hold 3 seconds, release 6. 5 reps twice daily. Vaginal delivery involves direct stretching and often tearing of the pelvic floor, so rebuild slowly and never push through pain or a heavy dragging sensation.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: 5-second holds. Month 4: elevator lifts. Month 5: add quick flicks.'),
  ('signs-to-watch-for-m2', 'physical_recovery'::mother_activity_category, 2, 'vaginal'::mother_activity_relevance, 'Signs to Watch For', 'Learn the signs so you can act early: a heaviness or dragging in the vagina, a bulge you can feel, worsening symptoms by evening or after standing, or difficulty inserting a tampon. Prolapse is common after vaginal delivery, rarely discussed, and highly responsive to physiotherapy when caught early. Noticing it is not alarmism.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 3: if any sign is present, book a women''s health physiotherapist rather than waiting.'),
  ('gentle-massage-longer-m3', 'physical_recovery'::mother_activity_category, 3, 'vaginal'::mother_activity_relevance, 'Gentle Massage, Longer', '4 minutes with warm oil, external and beginning internal if comfortable. The tissue should feel progressively softer week on week. If tightness persists, if intercourse is painful, or if you feel pulling at the scar, see a women''s health physiotherapist. These are treatable conditions and you do not have to accept them as permanent.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: 5 minutes. Month 5: reassess — taper if soft and comfortable, continue if not.'),
  ('squeeze-and-breathe-together-m3', 'physical_recovery'::mother_activity_category, 3, 'vaginal'::mother_activity_relevance, 'Squeeze and Breathe Together', 'Coordinate the contraction with your breath: exhale as you lift the pelvic floor, inhale as you release. This is how the pelvic floor works in real life — with the diaphragm, not against it. For vaginal delivery mothers this coordination is often disrupted by the birth and needs deliberate retraining.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 4: apply the same coordination during lifting and carrying throughout the day.'),
  ('inside-massage-m4', 'physical_recovery'::mother_activity_category, 4, 'vaginal'::mother_activity_relevance, 'Inside Massage', 'With clean hands and warm oil, apply gentle pressure at the vaginal opening, moving gradually deeper. Hold moderate downward pressure for a minute, then move slowly side to side. This is evidence-based scar tissue management. Seek guidance from a women''s health physiotherapist if the tissue feels tight or painful.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue monthly. A physio can provide in-session guidance and take-home technique.'),
  ('build-squeeze-stamina-m4', 'physical_recovery'::mother_activity_category, 4, 'vaginal'::mother_activity_relevance, 'Build Squeeze Stamina', '8-second holds, 10 reps, plus 10 quick flicks. Vaginal delivery mothers often have good fast-twitch response but poor endurance, or the reverse — training both deliberately addresses whichever is weaker. If you can hold 8 seconds but not repeat it, endurance is your gap.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 5: all four positions. Month 6: add during functional movement.'),
  ('ready-for-closeness-again-m4', 'physical_recovery'::mother_activity_category, 4, 'vaginal'::mother_activity_relevance, 'Ready for Closeness Again', 'Medical clearance usually comes at 6 weeks, but physical readiness and emotional readiness are separate things and both matter. If intercourse is painful, that is not something to push through or wait out — pain indicates scar tissue tightness or pelvic floor overactivity, both of which a women''s health physiotherapist treats effectively.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 6: if pain persists, seek a physio referral. Month 9: reassess.'),
  ('check-the-healing-at-5-months-m5', 'physical_recovery'::mother_activity_category, 5, 'vaginal'::mother_activity_relevance, 'Check the Healing at 5 Months', 'Assess the scar: is it soft and mobile, or tight and pulling? Any numbness, or sharp sensation on touch? Any discomfort during intercourse or when inserting a tampon? At 5 months the scar is still remodelling and remains highly responsive to massage and physiotherapy. Waiting does not improve it — treatment does.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: reassess. If tightness persists, a physio referral is warranted rather than optional.'),
  ('squeeze-while-you-move-m5', 'physical_recovery'::mother_activity_category, 5, 'vaginal'::mother_activity_relevance, 'Squeeze While You Move', 'Add a pelvic floor contraction to functional movement: exhale and lift as you stand from a chair, lift the baby, or climb stairs. This is the transfer point — a pelvic floor that works in isolation but not under load will not prevent leaking during real life.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: add during squats and lunges. Month 9: assess during impact activity.'),
  ('soften-the-scar-m6', 'physical_recovery'::mother_activity_category, 6, 'vaginal'::mother_activity_relevance, 'Soften the Scar', 'A warm bath for 5 minutes first, then gently massage the scar tissue in small circles for 3 minutes with clean hands. If comfortable and healed, continue with external perineal massage using warm oil. This is evidence-based and reduces the scar adhesions that cause long-term discomfort — most women are never told it exists.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 7: progress to internal perineal massage with physiotherapist guidance.'),
  ('test-before-jumping-or-running-m6', 'physical_recovery'::mother_activity_category, 6, 'vaginal'::mother_activity_relevance, 'Test Before Jumping or Running', 'Jump on the spot 10 times, then cough forcefully three times. Any leaking, heaviness, or dragging? If yes, do not progress to running, jumping, or high-impact exercise yet — see a women''s health physiotherapist. If no, you can begin gradual impact loading. This test is more informative than any timeline.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 9: repeat before beginning running. Month 12: repeat as a benchmark.'),
  ('inside-massage-keep-going-m7', 'physical_recovery'::mother_activity_category, 7, 'vaginal'::mother_activity_relevance, 'Inside Massage, Keep Going', '5 minutes, warm oil, internal massage with slow sustained pressure at any tight points. By month 7 the tissue should be noticeably more pliable than at month 4. If it is not, that is a clear indication for physiotherapy rather than continued self-management.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: reassess. If unchanged since month 4, book a physio.'),
  ('fast-and-slow-squeezes-m7', 'physical_recovery'::mother_activity_category, 7, 'vaginal'::mother_activity_relevance, 'Fast and Slow Squeezes', '10 slow 8-second holds, then 10 fast flicks, then 5 more slow holds. Combining fibre types in one session trains the pelvic floor the way it actually functions — sustained tone with rapid response when needed for a sneeze, cough, or lift.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 9: add in standing and during walking. Month 12: functional benchmark.'),
  ('check-the-signs-again-m8', 'physical_recovery'::mother_activity_category, 8, 'vaginal'::mother_activity_relevance, 'Check the Signs Again', 'Re-check the month 2 signs: heaviness or dragging, a bulge, symptoms worse by evening or after standing. Prolapse symptoms often appear or worsen around 6–9 months as women return to more activity and lifting. Appearing now does not mean you have done something wrong — it means the load has increased and the support needs strengthening.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'If any symptom is present, book a women''s health physiotherapist this month rather than monitoring further.'),
  ('tummy-and-squeeze-together-m8', 'physical_recovery'::mother_activity_category, 8, 'vaginal'::mother_activity_relevance, 'Tummy and Squeeze Together', 'Combine transverse abdominis engagement with the pelvic floor lift on the same exhale. Hold 5 seconds, release fully. 10 reps. These two systems work as a unit — training them separately builds each in isolation, but training them together is what produces continence and support during real movement.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 10: add during squats and lunges. Month 12: should be automatic during lifting.'),
  ('ready-to-run-check-this-first-m9', 'physical_recovery'::mother_activity_category, 9, 'vaginal'::mother_activity_relevance, 'Ready to Run? Check This First', 'Before beginning running: 10 single-leg hops each side, 10 jumps, 10 forceful coughs. Any leaking or heaviness means stop and see a physiotherapist first. Vaginal delivery mothers carry higher risk of stress incontinence with impact, and returning to running before the pelvic floor is ready causes problems that take far longer to resolve than waiting would have.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'If cleared, begin with 1-minute jog intervals. If not, continue strengthening and retest in 6 weeks.'),
  ('check-the-healing-at-9-months-m9', 'physical_recovery'::mother_activity_category, 9, 'vaginal'::mother_activity_relevance, 'Check the Healing at 9 Months', 'By 9 months the scar should be soft, pale, and mobile with no pain on touch or during intercourse. If any of those remain, this is the point to stop self-managing and get a referral. Scar tissue continues remodelling for up to 24 months, so intervention now still changes the long-term outcome substantially.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: final assessment. Bring any persistent issue to your 12-month appointment.'),
  ('squeeze-check-after-running-m10', 'physical_recovery'::mother_activity_category, 10, 'vaginal'::mother_activity_relevance, 'Squeeze Check After Running', 'If you have returned to running or jumping, check in after each session: any leaking, heaviness, or urgency during or after? The pelvic floor adapts to impact gradually and on its own timeline. Increase running volume by no more than 10% weekly, and treat any symptom as a signal to reduce load rather than to push through.', 5, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Continue this check at every new distance milestone throughout year 2.'),
  ('is-closeness-comfortable-now-m10', 'physical_recovery'::mother_activity_category, 10, 'vaginal'::mother_activity_relevance, 'Is Closeness Comfortable Now?', 'Ten months on, is intercourse comfortable? Persistent pain at this stage is not something to accept as your new normal. It usually indicates scar tissue restriction or pelvic floor overactivity, and both respond well to targeted physiotherapy. Many women never raise it because they assume it is simply how things are now. It isn''t.', 0, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: if unresolved, a physio referral should be a priority rather than a maybe.'),
  ('keep-the-scar-soft-m11', 'physical_recovery'::mother_activity_category, 11, 'vaginal'::mother_activity_relevance, 'Keep the Scar Soft', 'If the scar is soft, pale, and painless, you can taper massage to twice weekly as maintenance. If any tightness remains, continue daily and get a physio assessment. Tapering because time has passed rather than because the tissue has changed is the common error here.', 5, 'evening'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Month 12: monthly maintenance if fully resolved. Continue daily if not.'),
  ('squeeze-while-lifting-heavier-m11', 'physical_recovery'::mother_activity_category, 11, 'vaginal'::mother_activity_relevance, 'Squeeze While Lifting Heavier', 'Add pelvic floor engagement to increasingly heavy tasks: lifting the baby from the floor, carrying shopping, moving furniture. Exhale and lift on effort. This is what makes the pelvic floor genuinely functional rather than merely strong in isolation.', 5, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'moderate'::mother_activity_effort, 'Month 12: should be automatic and unconscious during everyday lifting.'),
  ('one-year-healing-check-m12', 'physical_recovery'::mother_activity_category, 12, 'vaginal'::mother_activity_relevance, 'One Year Healing Check', 'A full assessment at 12 months. Is the scar flat, pale, soft, and mobile? Any pain on touch, during intercourse, or when using a tampon? Any remaining tightness or pulling? Document it and raise anything unresolved at your 12-month appointment. Scar tissue remodels for up to 24 months, so this is midway, not the end.', 10, 'anytime'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Continue maintenance massage through months 18–24 if any tightness remains.'),
  ('one-year-squeeze-test-m12', 'physical_recovery'::mother_activity_category, 12, 'vaginal'::mother_activity_relevance, 'One Year Squeeze Test', 'Functional tests specific to this route: 10 ten-second holds without breath-holding, 10 quick flicks, jumping and coughing without leaking, running without urgency, and no heaviness by the end of the day. If any test fails at 12 months, see a women''s health physiotherapist. This is common but it is not normal, and it is fully treatable.', 10, 'morning'::mother_activity_time_of_day, 'no'::mother_activity_with_baby, 'gentle'::mother_activity_effort, 'Repeat annually for life. Pelvic floor fitness is a lifelong asset, not a postpartum phase.');
